/* ---------------------------------------------------------------------
 * 2. ユーティリティ
 * ------------------------------------------------------------------- */
function shuffle(arr){
  const a = arr.slice();
  for(let i=a.length-1;i>0;i--){
    const j = Math.floor(Math.random()*(i+1));
    [a[i],a[j]] = [a[j],a[i]];
  }
  return a;
}
function buildFreshDeck(){
  const deck = [];
  CARD_ORDER.forEach(id=>{
    const def = CARD_DEFS[id];
    for(let i=0;i<def.count;i++) deck.push(id);
  });
  return shuffle(deck);
}
function cardDef(id){ return CARD_DEFS[id]; }
function uniq(){ return Math.random().toString(36).slice(2,9); }
// 演出用のCPU「間」。ヘッドレステスト（__TEST_FORCE_CPU）実行時のみ短縮する。
function pace(ms){ return (typeof window!=='undefined' && window.__TEST_FORCE_CPU) ? Math.min(10, ms) : ms; }
// CPUの思考待ち時間。難易度ごとの倍率をかけた上でpace()に通す。
function cpuPace(ms){
  const diff = (typeof Game!=='undefined' && Game.difficulty && DIFFICULTY_DEFS[Game.difficulty]) ? DIFFICULTY_DEFS[Game.difficulty] : DIFFICULTY_DEFS.courtier;
  return pace(ms * diff.speedMul);
}

/* ---------------------------------------------------------------------
 * 2b. 難易度定義
 * ------------------------------------------------------------------- */
const DIFFICULTY_DEFS = {
  novice:   { id:'novice',   label:'新米仮面卿',   epithet:'駆け引きに不慣れで、隙が多い。',           speedMul:1.3 },
  courtier: { id:'courtier', label:'仮面卿',       epithet:'標準的な駆け引きをこなす、舞踏会の顔。',     speedMul:1.0 },
  wily:     { id:'wily',     label:'老獪な仮面卿', epithet:'記憶力と読みに長け、手強い相手。',           speedMul:0.78 },
};
const DIFFICULTY_ORDER = ['novice','courtier','wily'];

/* ---------------------------------------------------------------------
 * 2b-2. 対戦形式定義（CPU戦 / オンライン対戦）
 * ------------------------------------------------------------------- */
const MODE_DEFS = {
  cpu:    { id:'cpu',    label:'CPU対戦',     epithet:'仮面卿を相手に、腕試しの一局を。' },
  online: { id:'online', label:'オンライン対戦', epithet:'合言葉を交換して、対戦相手を見つけよう。' },
};
const MODE_ORDER = ['cpu','online'];

/* ---------------------------------------------------------------------
 * 2b-3. オンライン対戦の表示名（ランキングにも使う）
 * ------------------------------------------------------------------- */
const PLAYER_NAME_KEY = 'mascarade_player_name_v1';
// 表示名はログやランキングなど、他のプレイヤーの画面にもそのまま使われるため、
// HTMLとして解釈されうる文字をあらかじめ取り除いておく（入力時点で安全な形にする）。
function sanitizePlayerName(raw){
  let name = String(raw==null ? '' : raw).trim();
  name = name.replace(/[<>&"'`]/g, '');
  return name.slice(0, 12);
}
function loadPlayerName(){
  try{
    if(typeof localStorage==='undefined') return '';
    return sanitizePlayerName(localStorage.getItem(PLAYER_NAME_KEY) || '');
  }catch(e){ return ''; }
}
function savePlayerName(name){
  const clean = sanitizePlayerName(name);
  try{ if(typeof localStorage!=='undefined') localStorage.setItem(PLAYER_NAME_KEY, clean); }catch(e){}
  return clean;
}


/* ---------------------------------------------------------------------
 * 2c. 戦績（連勝）の永続化
 * ------------------------------------------------------------------- */
const STATS_KEY = 'mascarade_stats_v1';
function loadStats(){
  try{
    if(typeof localStorage==='undefined') return {};
    const raw = localStorage.getItem(STATS_KEY);
    return raw ? JSON.parse(raw) : {};
  }catch(e){ return {}; }
}
function saveStats(stats){
  try{
    if(typeof localStorage!=='undefined') localStorage.setItem(STATS_KEY, JSON.stringify(stats));
  }catch(e){ /* プライベートモード等で失敗しても致命的ではないので握りつぶす */ }
}
function ensureDiffStats(stats, diffId){
  if(!stats[diffId]) stats[diffId] = { wins:0, losses:0, draws:0, streak:0, best:0, played:0 };
  return stats[diffId];
}

// 前回選んだ難易度を覚えておき、次回起動時も同じ相手から始められるようにする
const LAST_DIFF_KEY = 'mascarade_last_difficulty_v1';
function loadLastDifficulty(){
  try{
    if(typeof localStorage==='undefined') return null;
    return localStorage.getItem(LAST_DIFF_KEY);
  }catch(e){ return null; }
}
function saveLastDifficulty(id){
  try{
    if(typeof localStorage!=='undefined') localStorage.setItem(LAST_DIFF_KEY, id);
  }catch(e){ /* 失敗しても致命的ではない */ }
}

/* ---------------------------------------------------------------------
 * 2d. 効果音（Web Audio APIで簡易合成。外部音源ファイルは使用しない）
 * ------------------------------------------------------------------- */
const SFX_KEY = 'mascarade_sfx_v1';
const SFX = {
  ctx: null,
  enabled: (function(){
    try{
      if(typeof localStorage==='undefined') return true;
      const v = localStorage.getItem(SFX_KEY);
      return v===null ? true : v==='1';
    }catch(e){ return true; }
  })(),

  setEnabled(v){
    this.enabled = !!v;
    try{ if(typeof localStorage!=='undefined') localStorage.setItem(SFX_KEY, v?'1':'0'); }catch(e){}
  },

  ensureCtx(){
    if(typeof window==='undefined') return null;
    if(!this.ctx){
      const AC = window.AudioContext || window.webkitAudioContext;
      if(!AC) return null;
      try{ this.ctx = new AC(); }catch(e){ return null; }
    }
    if(this.ctx.state==='suspended'){ this.ctx.resume().catch(()=>{}); }
    return this.ctx;
  },

  tone(freq, duration, type, gainPeak, delay){
    if(!this.enabled) return;
    const ctx = this.ensureCtx();
    if(!ctx) return;
    try{
      const t0 = ctx.currentTime + (delay||0);
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = type || 'sine';
      osc.frequency.setValueAtTime(freq, t0);
      gain.gain.setValueAtTime(0.0001, t0);
      gain.gain.linearRampToValueAtTime(gainPeak||0.14, t0+0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, t0+duration);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(t0); osc.stop(t0+duration+0.05);
    }catch(e){ /* 音声再生に失敗しても致命的ではない */ }
  },

  card(){ this.tone(360,0.11,'triangle',0.10); this.tone(540,0.09,'triangle',0.07,0.04); },
  turn(){ this.tone(660,0.16,'sine',0.08); },
  eliminate(){ this.tone(170,0.4,'sawtooth',0.09); this.tone(110,0.5,'sawtooth',0.07,0.09); },
  win(){ [523,659,784,1047].forEach((f,i)=>this.tone(f,0.32,'triangle',0.11,i*0.09)); },
  lose(){ [392,330,262].forEach((f,i)=>this.tone(f,0.38,'sine',0.08,i*0.12)); },
  click(){ this.tone(880,0.05,'square',0.045); },
};

/* ---------------------------------------------------------------------
 * 2b. BGM（背景音楽）
 * ------------------------------------------------------------------- */
const BGM_KEY = 'mascarade_bgm_v1';
const BGM = {
  el: null,
  started: false, // ブラウザの自動再生制限のため、最初のユーザー操作後に一度だけ再生を試みる
  enabled: (function(){
    try{
      if(typeof localStorage==='undefined') return false;
      const v = localStorage.getItem(BGM_KEY);
      return v===null ? false : v==='1'; // 初期状態（未設定）ではOFFにしておく
    }catch(e){ return false; }
  })(),

  setEnabled(v){
    this.enabled = !!v;
    try{ if(typeof localStorage!=='undefined') localStorage.setItem(BGM_KEY, v?'1':'0'); }catch(e){}
    if(this.enabled){ this.tryStart(); } else { this.pause(); }
  },

  getEl(){
    if(!this.el && typeof document!=='undefined'){
      this.el = document.getElementById('bgm-audio');
      if(this.el) this.el.volume = 0.38; // BGMは控えめな音量にしておく（SFXやセリフの邪魔をしないため）
    }
    return this.el;
  },

  // ユーザーの最初の操作（スプラッシュのタップ等）の直後に一度だけ呼ぶ。
  // ブラウザは「ユーザー操作を伴わない自動再生」を制限しているため、それより前には再生できない。
  tryStart(){
    if(this.started || !this.enabled) return;
    const el = this.getEl();
    if(!el) return;
    this.started = true;
    const p = el.play();
    if(p && typeof p.catch==='function'){
      p.catch(()=>{ this.started = false; }); // 再生がブロックされた場合は、次の操作で再挑戦できるようにする
    }
  },

  pause(){
    const el = this.getEl();
    if(el) el.pause();
  },

  resume(){
    if(!this.enabled) return;
    const el = this.getEl();
    if(!el) return;
    const p = el.play();
    if(p && typeof p.catch==='function') p.catch(()=>{});
  },
};

/* ---------------------------------------------------------------------
 * 3. ゲーム状態 & コアロジック
 * ------------------------------------------------------------------- */
const Game = {
  state: null,
  difficulty: (()=>{ const d = loadLastDifficulty(); return DIFFICULTY_DEFS[d] ? d : 'courtier'; })(),
  stats: loadStats(),
  mode: 'cpu', // 'cpu' | 'online'

  setDifficulty(id){
    if(DIFFICULTY_DEFS[id]){ this.difficulty = id; saveLastDifficulty(id); }
  },

  setMode(m){
    if(m==='cpu' || m==='online') this.mode = m;
  },

  // 山札・手札一式を新しく組み立てる（CPU戦、およびオンライン対戦のホスト側での部屋作成の両方から使う）
  buildFreshState(playerNames){
    const deckA = buildFreshDeck();
    const deckB = buildFreshDeck();
    const removedA = deckA.pop(); // 封印の仮面（誰にも見えない1枚、裏向きで除外）
    const removedB = deckB.pop();
    const players = [
      { id:0, name:playerNames[0], isCPU:false, hand:[deckA.pop()], alive:true, protectedFlag:false, skipNextTurn:false, discard:[] },
      { id:1, name:playerNames[1], isCPU:false, hand:[deckB.pop()], alive:true, protectedFlag:false, skipNextTurn:false, discard:[] },
    ];
    return {
      decks:[deckA, deckB], removedCards:[removedA, removedB],
      players,
      turnIndex: Math.random()<0.5 ? 0 : 1,
      turnCount: 0,
      log: [],
      phase: 'idle',       // idle | choose | resolve | over
      pendingCard: null,   // 選択済みだが未解決のカードID（対象/数字待ち）
      gameOver: false,
      winner: null,
      endReason: null,
    };
  },

  newGame(){
    // CPU戦のみここから直接始まる（オンライン対戦は Online.createRoom() / Online.joinRoom() 経由）
    const forceCPU = (typeof window!=='undefined' && window.__TEST_FORCE_CPU); // ヘッドレステスト専用フック
    const diff = DIFFICULTY_DEFS[this.difficulty] || DIFFICULTY_DEFS.courtier;
    CPU.rangeMemory = {}; // 前の対戦の記憶を持ち越さない
    CPU.bottomMemory = null;
    CPU.exactMemory = {};
    const state = this.buildFreshState(['あなた', diff.label]);
    state.players[0].isCPU = !!forceCPU;
    state.players[1].isCPU = true;
    state.isOnline = false;
    state.myIdx = 0;
    this.state = state;
    UI.showTable();
    this.addLog(`舞踏会の幕が上がる。両者の山札からそれぞれ1枚が「封印の仮面」として裏向きに除外された。最初の番は「${state.players[state.turnIndex].name}」。`, true);
    UI.render();
    // 最初の手番は、スタート画面から今まさに操作していた人が続けて見るので受け渡し演出は不要
    this.startTurn();
  },

  addLog(text, isTurnHeader){
    this.state.log.push({ text, header: !!isTurnHeader });
  },

  me(){ return this.state.players[this.state.myIdx || 0]; },
  opp(){ return this.state.players[Game.other(this.state.myIdx || 0)]; },
  other(idx){ return idx===0?1:0; },
  playerAt(idx){ return this.state.players[idx]; },

  startTurn(){
    const s = this.state;
    if(!s || s.gameOver) return;

    const p = s.players[s.turnIndex];
    // 大公に封じられている場合、山札の残数に関わらずこの番は何もできず終わる
    if(p.skipNextTurn){
      p.skipNextTurn = false;
      s.turnCount++;
      s.phase = 'idle';
      this.addLog(`── ${p.name} の番（${s.turnCount}巡）──`, true);
      this.addLog(`${p.name} は大公に封じられ、この番は何もできなかった。`);
      if(typeof UI!=='undefined' && UI.showTurnBanner){ UI.showTurnBanner(`${p.name}は封じられている`); }
      UI.render();
      setTimeout(()=>{ this.advanceTurn(); }, cpuPace(1200));
      return;
    }

    // 自分の山札が尽きた場合はここでゲーム終了（比べ合い）
    if(s.decks[s.turnIndex].length===0){
      this.endGameByShowdown();
      return;
    }

    this.revealTurn();
  },

  revealTurn(){
    const s = this.state;
    if(!s || s.gameOver) return;
    s.turnCount++;
    const p = s.players[s.turnIndex];

    p.protectedFlag = false; // 加護は自分の番が来た時点で解除
    const drawn = s.decks[s.turnIndex].pop();
    p.hand.push(drawn);
    s.lastDrawnCardId = drawn; // 手札枠側で「引いたばかりの1枚」に特別な演出を付けるための目印（同期対象外）
    this.addLog(`── ${p.name} の番（${s.turnCount}巡）──`, true);
    this.addLog(`${p.name} は山札から仮面を1枚引いた。`);
    if(typeof UI!=='undefined' && UI.showTurnBanner){ UI.showTurnBanner(`${p.name}の番`); }

    s.phase = 'choose';
    UI.render();

    if(p.isCPU){
      setTimeout(()=>CPU.takeTurn(), cpuPace(1500));
    }
  },

  /* 手札からカードを1枚選んで場に出す（プレイする） */
  discardCard(playerIdx, cardId, opts){
    opts = opts || {};
    const s = this.state;
    if(!s) return;
    const p = s.players[playerIdx];
    const idx = p.hand.indexOf(cardId);
    if(idx===-1){ console.error('hand mismatch', playerIdx, cardId, p.hand); return; }
    p.hand.splice(idx,1);
    p.discard.push(cardId);
    const def = cardDef(cardId);
    if(typeof SFX!=='undefined') SFX.card();

    if(!opts.forced){
      this.addLog(`${p.name} は「${def.name}（${def.number}）」の仮面を外し、場に出した。`);
    } else {
      this.addLog(`${p.name} は掟に従い「${def.name}（${def.number}）」を場に出した。`);
    }

    // 仮面の主催者は捨てられた瞬間に脱落
    if(def.exposeEliminates){
      if(opts.forced){
        // 他者の効果で捨てさせられた場合は、これまで通り自分だけが脱落する（道連れにはならない）
        this.eliminate(playerIdx, `「${def.name}」を捨てさせられ、正体が露見した`);
      } else {
        // 自らの意思で場に出した場合：自分は脱落するが、道連れに対象も退場させる（貴婦人の加護があれば対象は免れる）
        const otherIdx = this.other(playerIdx);
        const opp = s.players[otherIdx];
        this.playStage('mutualDestroy', playerIdx, otherIdx);
        this.eliminate(playerIdx, `「${def.name}」を自ら場に出し、正体を明かした`);
        if(opp.alive && opp.protectedFlag){
          this.addLog(`${opp.name}は貴婦人の加護により、道連れを免れた。`);
        } else if(opp.alive){
          this.eliminate(otherIdx, `${p.name}の道連れとなり、共に舞踏会を去った`);
        }
      }
      UI.render();
      if(this.checkGameEnd()) return;
      this.advanceTurn();
      return;
    }

    if(opts.forced || def.effect==='none'){
      // 効果を持たないカード（大公など）。このカードを出したことが今回の番の行動そのものであり、
      // これでターンは終了する（もう1枚は次の自分の番まで手札に残る）。
      UI.render();
      if(this.checkGameEnd()) return;
      this.advanceTurn();
      return;
    }

    // 効果解決フェーズへ
    s.phase = 'resolve';
    s.pendingCard = cardId;
    UI.render();
  },

  /* 有効な対象（生存していて、加護されていない相手）を1体返す（2人対戦なので常に相手固定） */
  validOpponentIdx(actorIdx){
    const t = this.other(actorIdx);
    const tp = this.playerAt(t);
    if(!tp.alive) return null;
    if(tp.protectedFlag) return null;
    return t;
  },

  /* ---------------- 各効果の解決 ---------------- */

  effGuessRank(actorIdx, guessNumber){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    const t = this.other(actorIdx);
    const target = this.playerAt(t);
    if(!target.alive || target.protectedFlag){
      this.notifyBlockedEffect(actorIdx, t, '給仕');
      this.finishResolve();
      return;
    }
    this.playStage('guessRank', actorIdx, t);
    const targetCard = target.hand[0];
    const hit = cardDef(targetCard).number === guessNumber;
    this.addLog(`${actor.name}は「${target.name}の手札は${guessNumber}」と宣言した…${hit?'的中！':'外れ。'}`);

    const resultHtml = hit
      ? `${actor.name}は${target.name}の手札を「${guessNumber}」と見抜いた！<br><br>${UI.cardInline(targetCard)}<br><br><b style="color:var(--gold-light)">${target.name}は正体を見破られ、退場する。</b>`
      : `${actor.name}は${target.name}の手札を「${guessNumber}」と宣言したが、<b>外れた</b>。<br>${target.name}の正体はまだ分からない。`;

    const applyResult = () => {
      if(hit){ this.eliminate(t, `${actor.name}の宣言が的中し、正体が見破られた`); }
      this.finishResolve();
    };
    UI.showInfoModal('給仕の宣言', resultHtml, applyResult, true);
  },

  // 楽団員：対象の手札が「高い(6-10)」か「低い(1-5)」かだけを知る（数字までは分からない部分情報）
  effPeekRange(actorIdx){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    const t = this.other(actorIdx);
    const target = this.playerAt(t);
    if(!target.alive || target.protectedFlag){
      this.notifyBlockedEffect(actorIdx, t, '楽団員');
      this.finishResolve();
      return;
    }
    const tCard = target.hand[0];
    const num = cardDef(tCard).number;
    const isHigh = num >= 6;
    this.playStage('peekRange', actorIdx, t);
    this.addLog(`${actor.name}は楽団の調べで${target.name}の仮面を推し量った。（数字は${isHigh?'6以上':'5以下'}）`);
    if(!actor.isCPU){
      UI.showInfoModal('楽団員の調べ', `${target.name}の仮面の数字は…<br><br><b style="font-size:20px; color:var(--gold-light);">${isHigh?'6以上':'5以下'}</b>`, ()=>{
        this.finishResolve();
      }, true);
    } else {
      CPU.rangeMemory[t] = isHigh; // CPUは大まかな範囲を記憶する
      this.finishResolve();
    }
  },

  // 預言者：対象の仮面を見抜き、その場にいる全員に公開させる
  effRevealHand(actorIdx){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    const t = this.other(actorIdx);
    const target = this.playerAt(t);
    if(!target.alive || target.protectedFlag){
      this.notifyBlockedEffect(actorIdx, t, '預言者');
      this.finishResolve();
      return;
    }
    const tCard = target.hand[0];
    const d = cardDef(tCard);
    this.playStage('revealHand', actorIdx, t);
    this.addLog(`${actor.name}は預言者の力で${target.name}の仮面を見抜き、その場に公開させた。正体は「${d.name}（${d.number}）」。`);
    CPU.exactMemory = CPU.exactMemory || {};
    CPU.exactMemory[t] = tCard; // 公開情報なのでCPUも正確に記憶する
    if(!actor.isCPU){
      UI.showInfoModal('預言者の暴露', `${target.name}の仮面が公開されました。<br><br>${UI.cardInline(tCard)}`, ()=>{
        this.finishResolve();
      }, true);
    } else {
      if(typeof UI!=='undefined' && UI.showToast){
        UI.showToast(`預言者の力であなたの正体「${d.name}（${d.number}）」が公開されました`, 'danger');
      }
      this.finishResolve();
    }
  },

  effProtectSelf(actorIdx){
    const actor = this.playerAt(actorIdx);
    actor.protectedFlag = true;
    this.playStage('protectSelf', actorIdx, actorIdx);
    this.addLog(`${actor.name}は「貴婦人」の加護を得た。次の自分の番までは狙われない。`);
    this.finishResolve();
  },

  // 密偵：自分の山札の一番上をこっそり確認し、そのまま戻すか底へ送るか選べる
  effPeekDeckTop(actorIdx){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    const myDeck = s.decks[actorIdx];
    if(myDeck.length===0){
      this.addLog(`${actor.name}は「密偵」を使ったが、自分の山札は残っていなかった。`);
      this.finishResolve();
      return;
    }
    const top = myDeck[myDeck.length-1];
    this.playStage('peekDeckTop', actorIdx, actorIdx);
    this.addLog(`${actor.name}は自分の山札の一番上をこっそり確認した。`);
    if(!actor.isCPU){
      UI.showInfoModal('密偵の報告', `あなたの山札の一番上は…<br><br>${UI.cardInline(top)}<br><br>このまま戻すか、山札の底へ送るか選んでください。`,
        null, true, [
          {label:'そのまま戻す', action:()=>{ this.addLog(`${actor.name}は山札をそのままにした。`); this.finishResolve(); }},
          {label:'底へ送る', action:()=>{ myDeck.pop(); myDeck.unshift(top); this.addLog(`${actor.name}は見た仮面を山札の底へ送った。`); this.finishResolve(); }},
        ]);
    } else {
      // CPUの選択（老獪な仮面卿は次に自分が引きたい仮面かどうかで判断する）
      const topNum = cardDef(top).number;
      let sendToBottom;
      if(Game.difficulty==='wily'){
        sendToBottom = topNum < 6; // 価値の低い仮面は先送りし、次に良い仮面を引きたい
      } else {
        sendToBottom = Math.random() < 0.5;
      }
      if(sendToBottom){ myDeck.pop(); myDeck.unshift(top); this.addLog(`${actor.name}は見た仮面を山札の底へ送ったようだ。`); }
      else { this.addLog(`${actor.name}は山札をそのままにしたようだ。`); }
      this.finishResolve();
    }
  },

  // 道化師：自分と対象、双方の手札を「公開でその場に捨てさせ」新しい仮面に総入れ替えする悪戯
  effDoubleRedraw(actorIdx){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    const t = this.other(actorIdx);
    const target = this.playerAt(t);
    if(!target.alive || target.protectedFlag){
      this.notifyBlockedEffect(actorIdx, t, '道化師');
      this.finishResolve();
      return;
    }
    // 入れ替え用の仮面が両者それぞれの山札に確保できない場合は空手札を作らないよう、そもそも発動させない
    // （自分と対象、それぞれが自分自身の山札から新しい仮面を引く）
    const availA = s.decks[actorIdx].length + (s.removedCards[actorIdx] ? 1 : 0);
    const availT = s.decks[t].length + (s.removedCards[t] ? 1 : 0);
    if(availA < 1 || availT < 1){
      this.addLog(`${actor.name}は「道化師」で悪戯しようとしたが、入れ替える仮面が山札に十分残っていなかった。`);
      this.finishResolve();
      return;
    }
    // MASQUERADEの黄金律：他者の効果で捨てさせられた場合、その仮面自体の効果は発動しない
    const drawOne = (p, deckIdx) => {
      const oldCard = p.hand.pop();
      p.discard.push(oldCard);
      let newCard = null;
      if(s.decks[deckIdx].length>0){ newCard = s.decks[deckIdx].pop(); }
      else if(s.removedCards[deckIdx]){ newCard = s.removedCards[deckIdx]; s.removedCards[deckIdx] = null; }
      if(newCard) p.hand.push(newCard);
      return oldCard;
    };
    const targetOld = drawOne(target, t);
    const actorOld = drawOne(actor, actorIdx);
    if(CPU.exactMemory){ delete CPU.exactMemory[actorIdx]; delete CPU.exactMemory[t]; }
    this.playStage('doubleRedraw', actorIdx, t);
    this.addLog(`${actor.name}は道化師の悪戯で、${target.name}と自分、双方の仮面を総入れ替えした。（${target.name}が手放したのは${cardDef(targetOld).name}、${actor.name}が手放したのは${cardDef(actorOld).name}）`);
    if(typeof UI!=='undefined' && UI.showToast){ UI.showToast(`🃏 ${actor.name}と${target.name}、双方の仮面が入れ替わった`, 'info'); }
    this.finishResolve();
  },

  // 毒見役：対象の仮面を誰にも見せぬまま密かに処分し、新しい仮面を引かせる
  effSecretRedraw(actorIdx){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    const t = this.other(actorIdx);
    const target = this.playerAt(t);
    if(!target.alive || target.protectedFlag){
      this.notifyBlockedEffect(actorIdx, t, '毒見役');
      this.finishResolve();
      return;
    }
    // 代わりの仮面が1枚も確保できない場合は、対象の手札を空にしないよう発動させない
    // （対象は自分自身の山札から新しい仮面を引く）
    const available = s.decks[t].length + (s.removedCards[t] ? 1 : 0);
    if(available < 1){
      this.addLog(`${actor.name}は「毒見役」を使おうとしたが、代わりの仮面が山札に残っていなかった。`);
      this.finishResolve();
      return;
    }
    // MASQUERADEの黄金律：他者の効果で処分された場合、その仮面自体の効果は発動しない。しかも今回は誰にも公開されない。
    const oldCard = target.hand.pop(); // あえて discard には加えない＝正体を明かさず密かに処分
    if(CPU.exactMemory){ delete CPU.exactMemory[t]; }
    this.playStage('secretRedraw', actorIdx, t);
    this.addLog(`${actor.name}は${target.name}の仮面を、誰にも見せぬまま密かに毒杯へ沈めた。`);
    let newCard = null;
    if(s.decks[t].length>0){ newCard = s.decks[t].pop(); }
    else if(s.removedCards[t]){ newCard = s.removedCards[t]; s.removedCards[t] = null; this.addLog('その山札が尽きていたため、封印されていた仮面が代わりに使われた。'); }
    target.hand.push(newCard);
    this.addLog(`${target.name}は山札から新しい仮面を引いた。`);
    if(typeof UI!=='undefined' && UI.showToast){ UI.showToast(`🍷 ${target.name}の仮面が、誰にも知られぬまま処分された`, 'info'); }
    this.finishResolve();
  },

  effCompareHand(actorIdx){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    const t = this.other(actorIdx);
    const target = this.playerAt(t);
    if(!target.alive || target.protectedFlag){
      this.notifyBlockedEffect(actorIdx, t, '黒騎士');
      this.finishResolve();
      return;
    }
    const aCard = actor.hand[0], tCard = target.hand[0];
    const aDef = cardDef(aCard), tDef = cardDef(tCard);
    this.playStage('compareHand', actorIdx, t);
    this.addLog(`${actor.name}と${target.name}は仮面の数字を見せ合った。（${actor.name}:${aDef.name} / ${target.name}:${tDef.name}）`);

    // MASQUERADEの黄金律：比べ合いによる公開だけでは脱落しない。数字の大小のみで決着する
    let loserIdx = null, outcomeText;
    if(aDef.number < tDef.number){ loserIdx = actorIdx; outcomeText = `<b style="color:var(--gold-light)">${target.name}の勝ち。</b>${actor.name}は数字で及ばず、正体が露見する。`; }
    else if(tDef.number < aDef.number){ loserIdx = t; outcomeText = `<b style="color:var(--gold-light)">${actor.name}の勝ち。</b>${target.name}は数字で及ばず、正体が露見する。`; }
    else { outcomeText = '数字は同じ。両者、決着つかず。'; }

    const applyResult = () => {
      if(loserIdx!==null){
        this.eliminate(loserIdx, loserIdx===actorIdx ? `${target.name}との対決に敗れた` : `${actor.name}との対決に敗れた`);
      } else {
        this.addLog('数字は同じだった。両者、決着つかず。');
      }
      this.finishResolve();
    };
    const modalHtml = `${actor.name}: ${UI.cardInline(aCard)}<br><br>${target.name}: ${UI.cardInline(tCard)}<br><br>${outcomeText}`;
    if(actor.isCPU && target.isCPU){
      applyResult();
    } else {
      UI.showInfoModal('黒騎士の対決', modalHtml, applyResult, true);
    }
  },

  // 大公：大公の権威で、対象と自分の仮面を強制的に交換させる
  // 大公：大公の権威で、対象の次の番を封じる（次の番、山札から引けず、なにもできないまま終わる）
  effSealTurn(actorIdx){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    const t = this.other(actorIdx);
    const target = this.playerAt(t);
    if(!target.alive || target.protectedFlag){
      this.notifyBlockedEffect(actorIdx, t, '大公');
      this.finishResolve();
      return;
    }
    target.skipNextTurn = true;
    this.playStage('sealTurn', actorIdx, t);
    this.addLog(`${actor.name}は大公の権威で、${target.name}の次の番を封じた。`);
    if(typeof UI!=='undefined' && UI.showToast){ UI.showToast(`👑 ${target.name}の次の番が封じられた`, 'info'); }
    if(!actor.isCPU){
      UI.showInfoModal('大公の封印', `${target.name}の次の番を封じました。相手は次の番、仮面を引くことも場に出すこともできません。`, ()=>{
        this.finishResolve();
      }, true);
    } else {
      this.finishResolve();
    }
  },

  finishResolve(){
    const s = this.state;
    if(!s) return;
    s.pendingCard = null;
    s.phase = 'idle';
    UI.render();
    if(this.checkGameEnd()) return;
    this.advanceTurn();
  },

  // 対象が既に退場している場合、または貴婦人の加護で守られている場合に、効果が不発に終わったことを伝える。
  // ログには常に記録し、さらに「効果を使った側」「守られた側」のどちらかがこの端末の視点であれば、
  // 見逃さないようトーストでも分かりやすく知らせる。
  notifyBlockedEffect(actorIdx, targetIdx, cardName){
    const s = this.state;
    const actor = this.playerAt(actorIdx);
    const target = this.playerAt(targetIdx);
    const protectedByLady = target.protectedFlag;
    this.addLog(`${actor.name} は「${cardName}」を使ったが、${protectedByLady?'貴婦人の加護で無効化された':'対象は既に退場していた'}。`);
    if(protectedByLady && typeof UI!=='undefined' && UI.showToast){
      const myIdx = (typeof s.myIdx==='number') ? s.myIdx : 0;
      if(myIdx===actorIdx){
        UI.showToast(`🛡 ${target.name}は貴婦人の加護で守られている`, 'info');
      } else if(myIdx===targetIdx){
        UI.showToast('🛡 貴婦人の加護が、あなたを守った！', 'info');
      }
    }
  },

  // この端末の視点（myIdx）から見て、行動側・対象側のどちらかに自分が含まれているかどうか。
  // 演出（effect-stage）は「自分に関係のある場面」でだけ再生する。
  isRelevantToMe(actorIdx, targetIdx){
    const s = this.state;
    if(!s || typeof s.myIdx!=='number') return true;
    return actorIdx===s.myIdx || targetIdx===s.myIdx;
  },

  // カード効果の演出（あれば）を再生する共通の入り口
  playStage(key, actorIdx, targetIdx){
    if(typeof UI==='undefined' || !UI.playEffectStage) return;
    if(targetIdx===undefined || this.isRelevantToMe(actorIdx, targetIdx)) UI.playEffectStage(key);
  },

  eliminate(playerIdx, reason){
    const s = this.state;
    const p = s.players[playerIdx];
    if(!p.alive) return;
    p.alive = false;
    // 残った手札は公開して捨て札へ
    while(p.hand.length){
      const c = p.hand.pop();
      p.discard.push(c);
    }
    this.addLog(`💀 ${p.name} は退場した。（${reason}）`);
    if(typeof SFX!=='undefined') SFX.eliminate();
    if(typeof UI!=='undefined' && UI.flashEliminated){ UI.flashEliminated(playerIdx); }
    if(typeof UI!=='undefined' && UI.showToast){ UI.showToast(`💀 ${p.name}が退場（${reason}）`, 'danger', 2600); }
  },

  checkGameEnd(){
    const s = this.state;
    const alive = s.players.filter(p=>p.alive);
    if(alive.length<=1){
      s.gameOver = true;
      s.winner = alive[0] || null;
      s.endReason = 'elimination';
      s.phase = 'over';
      this.recordResult();
      UI.render();
      // チュートリアル中は、通常の決着画面ではなくチュートリアル側の終了メッセージに任せる（二重表示を避ける）
      if(typeof Tutorial==='undefined' || !Tutorial.active) UI.showGameOver();
      return true;
    }
    return false;
  },

  endGameByShowdown(){
    const s = this.state;
    const alive = s.players.filter(p=>p.alive);
    let winner = null;
    if(alive.length===1){ winner = alive[0]; }
    else if(alive.length>1){
      let best = -1;
      alive.forEach(p=>{
        // 万一手札が空のプレイヤーがいても（想定外の経路で起きても）クラッシュしないよう防御しておく
        const n = p.hand[0] ? cardDef(p.hand[0]).number : -1;
        if(n>best){ best=n; winner=p; }
        else if(n===best){ winner=null; } // 同数タイは引き分け扱い
      });
    }
    s.gameOver = true;
    s.winner = winner;
    s.endReason = 'showdown';
    s.phase = 'over';
    this.recordResult();
    this.addLog('山札が尽きた。仮面を開き、最後の見比べが行われる。');
    UI.render();
    if(typeof Tutorial==='undefined' || !Tutorial.active) UI.showGameOver();
  },

  // 現在選択中の難易度に対する戦績（勝敗・連勝）を更新して保存する
  recordResult(){
    const s = this.state;
    if(s.isOnline){
      // オンライン対戦は難易度別の戦績には含めず、代わりにランキング（leaderboard）へ記録する
      if(typeof Online!=='undefined' && Online.recordMatchResult) Online.recordMatchResult();
      return;
    }
    const st = ensureDiffStats(this.stats, this.difficulty);
    st.played++;
    if(s.winner && s.winner.id===0){
      st.wins++; st.streak++; st.best = Math.max(st.best, st.streak);
    } else if(s.winner && s.winner.id===1){
      st.losses++; st.streak = 0;
    } else {
      st.draws++; st.streak = 0;
    }
    saveStats(this.stats);
  },

  // 現在選択中の難易度の戦績（勝敗数・連勝記録）をリセットする
  resetStats(diffId){
    diffId = diffId || this.difficulty;
    this.stats[diffId] = { wins:0, losses:0, draws:0, streak:0, best:0, played:0 };
    saveStats(this.stats);
    if(typeof UI!=='undefined' && UI.renderStatsPanel) UI.renderStatsPanel();
  },

  // 投了する（自分の枠＝myIdxが常に投了者。相手の番でもいつでも投了できる）
  concede(){
    const s = this.state;
    if(!s || s.gameOver) return;
    const concederIdx = (typeof s.myIdx==='number') ? s.myIdx : 0;
    const winnerIdx = this.other(concederIdx);
    const conceder = this.playerAt(concederIdx);
    const winner = this.playerAt(winnerIdx);
    this.addLog(`💀 ${conceder.name}は投了した。`);
    s.gameOver = true;
    s.winner = winner.alive ? winner : null;
    s.endReason = 'concede';
    s.phase = 'over';
    this.recordResult();
    UI.render();
    if(typeof Tutorial==='undefined' || !Tutorial.active) UI.showGameOver();
  },

  advanceTurn(){
    const s = this.state;
    if(!s || s.gameOver) return;
    s.turnIndex = this.other(s.turnIndex);
    s.phase = 'idle';
    const nextIsCPU = s.players[s.turnIndex].isCPU;
    setTimeout(()=>this.startTurn(), nextIsCPU ? cpuPace(900) : pace(350));
  },
};

/* ---------------------------------------------------------------------
 * 4. 簡易CPU AI
 * ------------------------------------------------------------------- */
const CPU = {
  memory: {},       // { playerIdx: cardId } 旧効果などで知った正確な情報の名残（現在は未使用の予備領域）
  rangeMemory: {},  // { playerIdx: boolean } 楽団員で知った「6以上/5以下」の大まかな情報
  bottomMemory: null, // 旧効果で見た「山札の底（最後の1枚）」の記憶（現在は未使用）

  // 山札・捨て札から見えている情報をもとに、まだ場に出ていない数字の残り枚数を数える
  // （excludeIdx を指定すると、そのプレイヤー自身の手札も「見えている」ものとして除外する）
  computeRemainingPool(excludeIdx){
    const s = Game.state;
    const remaining = {};
    CARD_ORDER.forEach(id=>{ const d = cardDef(id); remaining[d.number] = d.count; });
    const seen = [];
    s.players.forEach(pl=>seen.push(...pl.discard));
    if(excludeIdx!==undefined) seen.push(...s.players[excludeIdx].hand);
    seen.forEach(cid=>{
      const n = cardDef(cid).number;
      if(remaining[n]!==undefined) remaining[n] = Math.max(0, remaining[n]-1);
    });
    return remaining; // { number: 残り枚数 }
  },

  // 相手の手札の強さ（数字）を、見えている情報からざっくり見積もる
  estimateOpponentStrength(actorIdx){
    const t = Game.other(actorIdx);
    if(CPU.exactMemory && CPU.exactMemory[t] !== undefined){
      return cardDef(CPU.exactMemory[t]).number; // 預言者などで正確に分かっている
    }
    const pool = this.computeRemainingPool(actorIdx);
    let total=0, weighted=0;
    Object.keys(pool).forEach(n=>{ total += pool[n]; weighted += Number(n)*pool[n]; });
    let avg = total>0 ? weighted/total : 5.5;
    if(CPU.rangeMemory[t] !== undefined){
      // 楽団員で「6以上/5以下」が分かっていれば、その方向に見積もりを寄せる
      avg = CPU.rangeMemory[t] ? Math.max(avg, 7.5) : Math.min(avg, 3.5);
    }
    return avg;
  },

  // 給仕（数字当て）を使った場合の的中確率を、残りプールの偏り具合からざっくり見積もる
  estimateGuessConfidence(actorIdx){
    const t = Game.other(actorIdx);
    if(CPU.exactMemory && CPU.exactMemory[t] !== undefined) return 1; // 確実に当たる
    const pool = this.computeRemainingPool(actorIdx);
    let total = 0;
    Object.keys(pool).forEach(n=>{
      if(CPU.rangeMemory[t] !== undefined){
        const isHigh = CPU.rangeMemory[t];
        if(isHigh && Number(n) < 6) return;
        if(!isHigh && Number(n) > 5) return;
      }
      total += pool[n];
    });
    if(total<=0) return 0.1;
    // 候補が絞られているほど的中率が高い（最大でも1/candidateCountに近似）
    let candidateNumbers = 0;
    Object.keys(pool).forEach(n=>{
      if(CPU.rangeMemory[t] !== undefined){
        const isHigh = CPU.rangeMemory[t];
        if(isHigh && Number(n) < 6) return;
        if(!isHigh && Number(n) > 5) return;
      }
      if(pool[n]>0) candidateNumbers++;
    });
    return candidateNumbers>0 ? 1/candidateNumbers : 0.1;
  },

  takeTurn(){
    const s = Game.state;
    if(!s) return;
    const idx = s.turnIndex;
    const p = s.players[idx];
    if(!p.isCPU || s.phase!=='choose') return;

    const diffId = Game.difficulty || 'courtier';
    const hand = p.hand.slice();
    let chosen;
    // 「仮面の主催者」は絶対に自分からは出さない（もう1枚がある限り）
    if(hand.includes('masked_host') && hand.length===2){
      const nonHost = hand.find(c=>c!=='masked_host');
      // 両方とも「仮面の主催者」（別々の山札から1枚ずつ引き当てた場合）は、避けようがないので仕方なく1枚出す
      chosen = nonHost !== undefined ? nonHost : hand[0];
    } else if(diffId==='novice'){
      // 新米：ほとんど考えずランダムに選ぶ
      chosen = hand[Math.floor(Math.random()*hand.length)];
    } else {
      const t = Game.other(idx);
      const oppStrength = this.estimateOpponentStrength(idx);
      const scored = hand.map((c,i)=>{
        const d = cardDef(c);
        const n = d.number;
        const otherCard = hand[1-i];
        let score = (10-n) + Math.random() * (diffId==='wily' ? 2 : 4);
        if(diffId==='wily' && otherCard){
          const otherNum = cardDef(otherCard).number;
          // 給仕：残りプールの偏りから、当てやすい状況ほど優先する（捨て札からの数字推測の強化）
          if(d.effect==='guessRank'){
            const confidence = this.estimateGuessConfidence(idx);
            score += confidence * 8;
          }
          // 黒騎士：もう1枚の方が相手の見積もりより強ければ有利、弱ければ避ける
          if(d.effect==='compareHand'){
            if(otherNum > oppStrength + 0.5) score += 4;
            else if(otherNum < oppStrength - 0.5) score -= 4;
          }
          // 大公：相手が強そうな時ほど、番を封じる価値が高い
          if(d.effect==='sealTurn' && oppStrength >= 6.5) score += 3;
          // 貴婦人：もう1枚が高価値なほど、温存して守る価値が高い（防御的なカード温存）
          if(d.effect==='protectSelf' && otherCard){
            score += Math.max(0, otherNum - 4) * 1.3;
          }
        }
        return { c, score };
      });
      scored.sort((a,b)=>b.score-a.score);
      chosen = scored[0].c;
    }

    Game.discardCard(idx, chosen);

    // discardCard は効果を持たないカード（大公など）や「仮面の主催者」露見の場合、
    // 自分でターンを終わらせる。ここでは効果解決待ち(resolveフェーズ)の場合のみ担当する。
    setTimeout(()=>{
      if(!Game.state || Game.state.gameOver) return;
      if(Game.state.pendingCard === chosen && Game.state.phase==='resolve'){
        this.resolvePending(idx, chosen);
      }
    }, cpuPace(1100));
  },

  guessWeightedNumber(actorIdx){
    const diffId = Game.difficulty || 'courtier';
    if(diffId==='novice'){
      // 新米：情報を活かさずほぼランダムに宣言する
      return 1 + Math.floor(Math.random()*10);
    }
    // 預言者などで対象の正体を正確に知っていれば、迷わずそれを宣言する
    const t = Game.other(actorIdx);
    if(CPU.exactMemory && CPU.exactMemory[t] !== undefined){
      return cardDef(CPU.exactMemory[t]).number;
    }
    const remaining = this.computeRemainingPool(actorIdx);
    // 楽団員で知った「6以上/5以下」の大まかな記憶があれば、その範囲内から絞り込む
    let pool = [];
    Object.keys(remaining).forEach(n=>{
      for(let i=0;i<remaining[n];i++) pool.push(Number(n));
    });
    if(CPU.rangeMemory[t] !== undefined){
      const isHigh = CPU.rangeMemory[t];
      const narrowed = pool.filter(n => isHigh ? n>=6 : n<=5);
      if(narrowed.length>0) pool = narrowed;
    }
    if(pool.length===0) return 1 + Math.floor(Math.random()*10);
    return pool[Math.floor(Math.random()*pool.length)];
  },

  resolvePending(actorIdx, cardId){
    const def = cardDef(cardId);
    switch(def.effect){
      case 'guessRank': Game.effGuessRank(actorIdx, this.guessWeightedNumber(actorIdx)); break;
      case 'peekRange': Game.effPeekRange(actorIdx); break;
      case 'revealHand': Game.effRevealHand(actorIdx); break;
      case 'protectSelf': Game.effProtectSelf(actorIdx); break;
      case 'peekDeckTop': Game.effPeekDeckTop(actorIdx); break;
      case 'doubleRedraw': Game.effDoubleRedraw(actorIdx); break;
      case 'secretRedraw': Game.effSecretRedraw(actorIdx); break;
      case 'compareHand': Game.effCompareHand(actorIdx); break;
      case 'sealTurn': Game.effSealTurn(actorIdx); break;
      default: Game.finishResolve();
    }
  },
};

/* ---------------------------------------------------------------------
 * 4b. オンライン対戦（Firebase Firestore）
 * ------------------------------------------------------------------- */
/*
 * 【重要：ご自身のFirebaseプロジェクトが必要です】
 * 下の firebaseConfig に、ご自身の Firebase プロジェクトの設定値を貼り付けてください。
 * 設定方法・必要なFirestoreセキュリティルールは README.md を参照してください。
 *
 * 【この実装の設計方針について】
 * 対戦相手の手札を本当の意味で秘匿する（サーバー側だけが両者の手札を見られる）には
 * Cloud Functions 等の有料プランの仕組みが必要になります。今回はクライアントのみで
 * 完結する構成（Firestoreの無料枠内）を優先し、「部屋の参加者2人だけが読み書きできる」
 * という Firestore のセキュリティルールで保護しつつ、画面上は相手の手札を表示しない
 * という設計にしています。つまり、開発者ツール等でネットワーク通信を覗けば理論上は
 * 相手の手札を先に知ることも可能です（このゲームがこれまで採用していた「1台のスマホの
 * 受け渡し」方式が性善説に頼っていたのと同種の前提です）。カジュアルに友人と遊ぶ用途を
 * 想定した割り切りですので、ご了承ください。
 */
