const ROOM_CODE_CHARS = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'; // 紛らわしい 0/O・1/I/L を除外
function generateRoomCode(len){
  len = len || 5;
  let code = '';
  for(let i=0;i<len;i++) code += ROOM_CODE_CHARS[Math.floor(Math.random()*ROOM_CODE_CHARS.length)];
  return code;
}

// Firestoreは「配列の中に配列を直接ネストする」形式（array of arrays）を書き込めない。
// ゲーム内部では s.decks を [自分の山札, 相手の山札] という配列の配列として扱っているため、
// Firestoreへ送る直前だけ {d0:[...], d1:[...]} というオブジェクト形式に変換し、
// 受け取った直後に元の配列形式へ戻す。ゲームロジック本体（s.decks[0] 等の参照）は変更しない。
function serializeStateForFirestore(state){
  const clean = Object.assign({}, state);
  delete clean.isOnline;
  delete clean.myIdx;
  if(Array.isArray(clean.decks)){
    clean.decks = { d0: clean.decks[0] || [], d1: clean.decks[1] || [] };
  }
  return clean;
}
function deserializeStateFromFirestore(data){
  const state = Object.assign({}, data);
  if(state.decks && !Array.isArray(state.decks)){
    state.decks = [state.decks.d0 || [], state.decks.d1 || []];
  }
  return state;
}

const Online = {
  db: null,
  uid: null,
  roomCode: null,
  role: null,        // 'host' | 'guest'
  unsubscribe: null,
  panelState: 'idle', // 'idle' | 'creating' | 'waiting' | 'joining' | 'error'
  errorMsg: '',
  syncTimer: null,
  ready: false,       // Firebase初期化＋匿名サインインが完了したか

  isConfigured(){
    return firebaseConfig.apiKey && firebaseConfig.apiKey !== 'YOUR_API_KEY';
  },

  // Firebaseの初期化と匿名サインインを行う（初回のみ）。完了したらcallbackを呼ぶ。
  // 万一どこかの通信が固まって応答が返ってこなくても、画面が無反応のまま止まり続けないよう
  // タイムアウトを設けている（「部屋を準備しています…」で無限に止まってしまう不具合の対策）。
  ensureReady(callback){
    if(this.ready){ callback(); return; }
    if(typeof firebase==='undefined' || !this.isConfigured()){
      this.panelState = 'error';
      this.errorMsg = 'firebaseConfig が未設定です。README.md の手順に従い、ご自身のFirebaseプロジェクトの設定値を貼り付けてください。';
      UI.renderOnlinePanel();
      return;
    }
    let settled = false;
    const timeoutId = setTimeout(()=>{
      if(settled) return;
      settled = true;
      this.panelState = 'error';
      this.errorMsg = '接続がタイムアウトしました（15秒応答なし）。通信環境をご確認のうえ、Firestoreデータベースが作成済みか、セキュリティルールが公開されているかもあわせてご確認ください。';
      UI.renderOnlinePanel();
    }, 15000);
    try{
      if(!firebase.apps || !firebase.apps.length) firebase.initializeApp(firebaseConfig);
      this.db = firebase.firestore();
      const unsubscribe = firebase.auth().onAuthStateChanged((user)=>{
        if(user && !settled){
          settled = true;
          clearTimeout(timeoutId);
          if(typeof unsubscribe==='function') unsubscribe(); // 1回で用済みなので解除する（重複登録を避ける）
          this.uid = user.uid;
          this.ready = true;
          callback();
        }
      });
      firebase.auth().signInAnonymously().catch((err)=>{
        if(settled) return;
        settled = true;
        clearTimeout(timeoutId);
        console.error('[MASQUERADE] Firebase匿名サインイン失敗:', err);
        this.panelState = 'error';
        const code = err && err.code ? err.code : '';
        if(code === 'auth/admin-restricted-operation' || code === 'auth/operation-not-allowed'){
          this.errorMsg = `匿名認証が有効になっていません（${code}）。Firebaseコンソールの「Authentication」→「Sign-in method」から「匿名」を有効にしてください。`;
        } else if(code === 'auth/network-request-failed'){
          this.errorMsg = `ネットワークエラーです（${code}）。通信環境をご確認のうえ、もう一度お試しください。`;
        } else if(code === 'auth/invalid-api-key' || code === 'auth/api-key-not-valid'){
          this.errorMsg = `firebaseConfig の apiKey が正しくないようです（${code}）。Firebaseコンソールの設定値と見比べてください。`;
        } else {
          this.errorMsg = `サインインに失敗しました（${code || (err && err.message) || '不明なエラー'}）。匿名認証が有効になっているか確認してください。`;
        }
        UI.renderOnlinePanel();
      });
    } catch(err){
      clearTimeout(timeoutId);
      this.panelState = 'error';
      this.errorMsg = `Firebaseの初期化に失敗しました（${err.message}）。`;
      UI.renderOnlinePanel();
    }
  },

  startCreate(){
    this.panelState = 'creating';
    this.errorMsg = '';
    UI.renderOnlinePanel();
    this.ensureReady(()=>this._createRoom());
  },

  _createRoom(){
    const code = generateRoomCode();
    CPU.rangeMemory = {}; CPU.bottomMemory = null; CPU.exactMemory = {};
    // ホストの表示名を反映する（未設定なら仮の呼び名）。ゲスト側は参加時に自分の名前へ更新する。
    const hostName = loadPlayerName() || '名もなき仮面卿';
    const state = Game.buildFreshState([hostName, '対戦相手を待っています']);
    let settled = false;
    const timeoutId = setTimeout(()=>{
      if(settled) return;
      settled = true;
      this.panelState = 'error';
      this.errorMsg = '部屋の作成がタイムアウトしました（15秒応答なし）。Firestoreデータベースが作成済みか、セキュリティルールが公開されているかをご確認ください。';
      UI.renderOnlinePanel();
    }, 15000);
    this.db.collection('rooms').doc(code).set({
      hostUid: this.uid,
      guestUid: null,
      status: 'waiting',
      state: serializeStateForFirestore(state),
      createdAt: Date.now(),
      updatedAt: Date.now(),
    }).then(()=>{
      if(settled) return;
      settled = true;
      clearTimeout(timeoutId);
      this.roomCode = code;
      this.role = 'host';
      this.panelState = 'waiting';
      UI.renderOnlinePanel();
      this._listen(code);
    }).catch((err)=>{
      if(settled) return;
      settled = true;
      clearTimeout(timeoutId);
      this.panelState = 'error';
      this.errorMsg = `部屋の作成に失敗しました（${err.code || err.message}）。`;
      UI.renderOnlinePanel();
    });
  },

  startJoin(codeInput){
    const code = (codeInput || '').trim().toUpperCase();
    if(!code){ return; }
    this.panelState = 'joining';
    this.errorMsg = '';
    UI.renderOnlinePanel();
    this.ensureReady(()=>this._joinRoom(code));
  },

  _joinRoom(code){
    let settled = false;
    const timeoutId = setTimeout(()=>{
      if(settled) return;
      settled = true;
      this.panelState = 'error';
      this.errorMsg = '接続がタイムアウトしました（15秒応答なし）。通信環境や合言葉をご確認のうえ、もう一度お試しください。';
      UI.renderOnlinePanel();
    }, 15000);
    const ref = this.db.collection('rooms').doc(code);
    ref.get().then((doc)=>{
      if(!doc.exists){
        if(settled) return;
        settled = true;
        clearTimeout(timeoutId);
        this.panelState = 'error';
        this.errorMsg = `合言葉「${code}」の部屋が見つかりませんでした。`;
        UI.renderOnlinePanel();
        return;
      }
      const data = doc.data();
      if(data.status !== 'waiting' || data.guestUid){
        if(settled) return;
        settled = true;
        clearTimeout(timeoutId);
        this.panelState = 'error';
        this.errorMsg = 'この部屋はすでに満員か、対戦が終了しています。';
        UI.renderOnlinePanel();
        return;
      }
      // ゲストの表示名を、待機中だったプレースホルダーへ上書きする
      const guestName = loadPlayerName() || '名もなき仮面卿';
      const newState = data.state;
      if(newState && newState.players && newState.players[1]) newState.players[1].name = guestName;
      return ref.update({
        guestUid: this.uid,
        status: 'playing',
        state: newState,
        updatedAt: Date.now(),
      }).then(()=>{
        if(settled) return;
        settled = true;
        clearTimeout(timeoutId);
        this.roomCode = code;
        this.role = 'guest';
        this._listen(code);
      });
    }).catch((err)=>{
      if(settled) return;
      settled = true;
      clearTimeout(timeoutId);
      this.panelState = 'error';
      const code2 = err && err.code ? err.code : '';
      if(code2 === 'permission-denied'){
        this.errorMsg = `参加に失敗しました（${code2}）。Firestoreのセキュリティルールが、部屋への参加（guestUidの書き込み）を許可する内容になっているかご確認ください（README.mdの最新のルールをご参照ください）。`;
      } else {
        this.errorMsg = `参加に失敗しました（${code2 || (err && err.message) || '不明なエラー'}）。`;
      }
      UI.renderOnlinePanel();
    });
  },

  _listen(code){
    if(this.unsubscribe) this.unsubscribe();
    this.lastSeenChatAt = 0;
    this.unsubscribe = this.db.collection('rooms').doc(code).onSnapshot((doc)=>{
      if(!doc.exists) return;
      const data = doc.data();
      // 相手からの簡易メッセージを検知して表示する（自分が送った分は表示しない）
      if(data.chatAt && data.chatAt > (this.lastSeenChatAt||0)){
        this.lastSeenChatAt = data.chatAt;
        if(data.chatFrom && data.chatFrom !== this.uid && data.chatText){
          if(typeof UI!=='undefined' && UI.showChatBubble) UI.showChatBubble(data.chatText);
        }
      }
      // 相手側のハートビート（生存確認）を記録しておく
      if(this.role){
        const opponentField = this.role==='host' ? 'guestLastSeen' : 'hostLastSeen';
        if(data[opponentField]) this._opponentLastSeen = data[opponentField];
      }
      // 相手が明示的に退出した場合は、タイムアウトを待たずすぐに知らせ、対局を終了状態にする
      if(data.status==='abandoned' && Game.state && Game.state.isOnline && !Game.state.gameOver){
        Game.state.gameOver = true;
        Game.state.phase = 'over';
        Game.state.endReason = 'opponent_left';
        UI.render();
        if(typeof UI!=='undefined' && UI.showOpponentLeftNotice) UI.showOpponentLeftNotice();
        return;
      }
      if((data.status==='playing' || data.status==='over') && data.hostUid && data.guestUid){
        this._enterGame(data);
      } else if(data.status==='waiting'){
        this.panelState = 'waiting';
        UI.renderOnlinePanel();
      }
    }, (err)=>{
      this.panelState = 'error';
      this.errorMsg = `接続エラーが発生しました（${err.code || err.message}）。`;
      UI.renderOnlinePanel();
    });
  },

  // 部屋のFirestoreデータを Game.state に反映する（ゲスト参加を検知した直後、および以降の同期受信の両方で使う）
  _enterGame(data){
    Game._applyingRemote = true;
    const myIdx = this.role === 'host' ? 0 : 1;
    Game.state = Object.assign({}, deserializeStateFromFirestore(data.state), { isOnline:true, myIdx });
    if(!this.heartbeatTimer) this.startHeartbeat(); // 二重に開始しないよう、まだ動いていない時だけ始める

    // 対局の決着を、受け取った側（＝行動していない側）でもきちんと表示する
    // （行動した側はconcede()等の中で既に表示済みなので、二重に出さないようガードする）
    if(Game.state.gameOver && !this._gameOverShown){
      this._gameOverShown = true;
      if(!document.getElementById('table').classList.contains('open')) UI.showTable();
      UI.render();
      if(typeof Tutorial==='undefined' || !Tutorial.active) UI.showGameOver();
      Game._applyingRemote = false;
      return;
    }
    if(!Game.state.gameOver) this._gameOverShown = false; // 再戦等でgameOverがfalseに戻ったら、次回また表示できるようにする

    // 「最初のターンを始める」処理は、対局の立ち上がり（turnCount===0）の時だけ行う。
    // ここにガードを入れないと、ホスト自身が送った更新が自分に返ってくるたびに
    // startTurn()が二重に呼ばれ、山札から余分にカードを引いてしまう不具合につながる
    // （実際に「相手の手札が増え続ける」不具合として発生していたもの）。
    if(Game.state.phase==='idle' && Game.state.turnCount===0 && !this._kickoffInProgress){
      if(this.role==='host'){
        this._kickoffInProgress = true;
        Game._applyingRemote = false;
        UI.showTable();
        Game.addLog(`舞踏会の幕が上がる。両者の山札からそれぞれ1枚が「封印の仮面」として裏向きに除外された。最初の番は「${Game.state.players[Game.state.turnIndex].name}」。`, true);
        UI.render();
        Game.startTurn();
        setTimeout(()=>{ this._kickoffInProgress = false; }, 2000); // 開始処理が確実に終わった後、ロックを解除する
        return;
      }
    }
    if(!document.getElementById('table').classList.contains('open')) UI.showTable();
    UI.render();
    Game._applyingRemote = false;
  },

  // 対戦相手へ簡易メッセージ（定型文）を送る
  sendChat(text){
    if(!this.roomCode || !this.db) return;
    this.db.collection('rooms').doc(this.roomCode).update({
      chatText: text,
      chatFrom: this.uid,
      chatAt: Date.now(),
    }).catch((err)=>{ console.error('chat send failed', err); });
  },

  // オンライン対戦の結果を、自分自身のランキング（leaderboard）記録へ反映する。
  // セキュリティルール上、各プレイヤーは自分のuidの文書にしか書き込めないため、
  // 対局に参加した両者が、それぞれ自分の結果を自分で記録する形になっている。
  recordMatchResult(){
    if(!this.db || !this.uid) return;
    const s = Game.state;
    if(!s) return;
    const myIdx = (typeof s.myIdx==='number') ? s.myIdx : 0;
    let outcome; // 'win' | 'loss' | 'draw'
    if(!s.winner) outcome = 'draw';
    else outcome = (s.winner.id===myIdx) ? 'win' : 'loss';
    const myName = loadPlayerName() || (s.players[myIdx] && s.players[myIdx].name) || '名もなき仮面卿';

    const ref = this.db.collection('leaderboard').doc(this.uid);
    this.db.runTransaction((tx)=>{
      return tx.get(ref).then((doc)=>{
        const cur = doc.exists ? doc.data() : { points:0, wins:0, losses:0, draws:0, streak:0, bestStreak:0 };
        let { points=0, wins=0, losses=0, draws=0, streak=0, bestStreak=0 } = cur;
        if(outcome==='win'){ points+=3; wins+=1; streak+=1; bestStreak=Math.max(bestStreak, streak); }
        else if(outcome==='draw'){ points+=1; draws+=1; streak=0; }
        else { losses+=1; streak=0; }
        tx.set(ref, {
          name: sanitizePlayerName(myName) || '名もなき仮面卿',
          points, wins, losses, draws, streak, bestStreak,
          updatedAt: Date.now(),
        }, { merge:true });
      });
    }).catch((err)=>{
      console.error('[MASQUERADE] ランキングの記録に失敗:', err);
    });
  },

  // 同じ相手・同じ部屋のまま、もう一度対局を始める
  rematch(){
    if(!this.roomCode || !this.db) return;
    CPU.rangeMemory = {}; CPU.bottomMemory = null; CPU.exactMemory = {};
    const s = Game.state;
    const hostName = (s && s.players[0] && s.players[0].name) || 'プレイヤー1';
    const guestName = (s && s.players[1] && s.players[1].name) || 'プレイヤー2';
    const freshState = Game.buildFreshState([hostName, guestName]);
    this.db.collection('rooms').doc(this.roomCode).update({
      state: serializeStateForFirestore(freshState),
      status: 'playing',
      updatedAt: Date.now(),
    }).catch((err)=>{
      if(typeof UI!=='undefined' && UI.showToast) UI.showToast('再戦の開始に失敗しました', 'danger');
      console.error('[MASQUERADE] 再戦の開始に失敗:', err);
    });
  },

  // ランキング上位を取得する（多い順に指定件数）
  fetchLeaderboard(limit){
    if(!this.db) return Promise.resolve([]);
    return this.db.collection('leaderboard').orderBy('points','desc').limit(limit||20).get()
      .then((snap)=>{
        const rows = [];
        snap.forEach(doc=> rows.push(Object.assign({ uid: doc.id }, doc.data())));
        return rows;
      });
  },

  // 自分の操作でGame.stateが変化した時、少し間を置いてFirestoreへ書き戻す（連続書き込みをまとめる）
  scheduleSync(){
    if(!this.roomCode || !this.db) return;
    clearTimeout(this.syncTimer);
    this.syncTimer = setTimeout(()=>this._pushState(), 150);
  },

  _pushState(){
    if(!this.roomCode || !this.db || !Game.state) return;
    this.db.collection('rooms').doc(this.roomCode).update({
      state: serializeStateForFirestore(Game.state),
      status: Game.state.gameOver ? 'over' : 'playing',
      updatedAt: Date.now(),
    }).catch((err)=>{
      if(typeof UI!=='undefined' && UI.showToast) UI.showToast('通信エラー：相手に伝わっていない可能性があります', 'danger');
      console.error('online sync failed', err);
    });
  },

  leaveRoom(){
    this.stopHeartbeat();
    if(this.unsubscribe){ this.unsubscribe(); this.unsubscribe = null; }
    if(this.roomCode && this.db){
      this.db.collection('rooms').doc(this.roomCode).update({ status:'abandoned', updatedAt: Date.now() }).catch(()=>{});
    }
    this.roomCode = null;
    this.role = null;
    this.panelState = 'idle';
    this.errorMsg = '';
    this._gameOverShown = false;
    this._kickoffInProgress = false;
  },

  // ハートビート：自分がまだこの対局に接続していることを、定期的にFirestoreへ書き込んで伝える。
  // 相手側はこの更新時刻の間隔から、通信が途切れていないかを判断する。
  startHeartbeat(){
    this.stopHeartbeat();
    const beat = ()=>{
      if(!this.roomCode || !this.db || !this.role) return;
      const field = this.role==='host' ? 'hostLastSeen' : 'guestLastSeen';
      this.db.collection('rooms').doc(this.roomCode).update({ [field]: Date.now() }).catch(()=>{});
    };
    beat();
    this.heartbeatTimer = setInterval(beat, 10000); // 10秒ごとに自分の生存を伝える
    this.staleTimer = setInterval(()=>this._checkOpponentStale(), 5000); // 5秒ごとに相手の様子を確認する
  },

  stopHeartbeat(){
    if(this.heartbeatTimer){ clearInterval(this.heartbeatTimer); this.heartbeatTimer = null; }
    if(this.staleTimer){ clearInterval(this.staleTimer); this.staleTimer = null; }
    this._opponentLastSeen = null;
    this._staleWarned = false;
  },

  // 相手の最終確認時刻から一定時間が経っていたら「反応がない」と判断し、案内を表示する
  _checkOpponentStale(){
    if(!Game.state || !Game.state.isOnline) return;
    if(this._opponentLastSeen == null) return; // まだ相手の情報を受け取っていない
    const elapsed = Date.now() - this._opponentLastSeen;
    if(elapsed > 25000 && !this._staleWarned){
      this._staleWarned = true;
      UI.showOpponentStaleWarning();
    } else if(elapsed <= 25000 && this._staleWarned){
      this._staleWarned = false; // 再び反応があれば、警告状態を解除する
      if(typeof UI!=='undefined' && UI.hideOpponentStaleWarning) UI.hideOpponentStaleWarning();
    }
  },

  resetPanel(){
    this.panelState = 'idle';
    this.errorMsg = '';
    UI.renderOnlinePanel();
  },

  // 「サインイン→書き込み→読み取り→削除」を実際に1つずつ試し、どの段階で失敗しているかを
  // 具体的に表示する診断ツール。「部屋を準備しています…」等で原因が分からず止まってしまう
  // 場合に、ご自身で問題を切り分けられるようにするためのもの。
  runDiagnostics(){
    const log = [];
    const render = (running)=>{
      const el = document.getElementById('online-panel');
      if(!el) return;
      el.innerHTML = `
        <div class="online-status-text" style="text-align:left; white-space:pre-wrap; line-height:1.9;">${log.join('\n')}</div>
        ${running ? '<div class="online-status-text">実行中<span class="online-waiting-dot"></span><span class="online-waiting-dot"></span><span class="online-waiting-dot"></span></div>' : ''}
        <div class="online-choice-row" style="margin-top:10px;">
          <button class="btn" onclick="Online.resetPanel()">戻る</button>
        </div>
      `;
    };
    log.push('① firebaseConfig の確認…');
    render(true);
    if(!this.isConfigured()){
      log.push('　→ ✕ firebaseConfig が未設定のままです。');
      render(false);
      return;
    }
    log.push('　→ ✓ 設定済み');

    log.push('② SDKの読み込み確認…');
    if(typeof firebase==='undefined'){
      log.push('　→ ✕ Firebase SDK が読み込めていません（通信環境をご確認ください）。');
      render(false);
      return;
    }
    log.push('　→ ✓ 読み込み済み');
    render(true);

    try{
      if(!firebase.apps || !firebase.apps.length) firebase.initializeApp(firebaseConfig);
      this.db = firebase.firestore();
    }catch(err){
      log.push(`　→ ✕ 初期化エラー：${err.message}`);
      render(false);
      return;
    }

    log.push('③ 匿名サインインを試行中…');
    render(true);
    const signInTimeout = setTimeout(()=>{
      log.push('　→ ✕ タイムアウト（10秒応答なし）。匿名認証が有効になっているかご確認ください。');
      render(false);
    }, 10000);

    firebase.auth().signInAnonymously().then(()=>{
      // onAuthStateChangedで確定するのを待つ
    }).catch((err)=>{
      clearTimeout(signInTimeout);
      log.push(`　→ ✕ サインイン失敗：${err.code || err.message}`);
      if(err.code==='auth/admin-restricted-operation' || err.code==='auth/operation-not-allowed'){
        log.push('　　（Firebaseコンソールの Authentication → Sign-in method で「匿名」を有効にしてください）');
      }
      render(false);
    });

    let authDone = false;
    firebase.auth().onAuthStateChanged((user)=>{
      if(!user || authDone) return;
      authDone = true;
      clearTimeout(signInTimeout);
      log.push(`　→ ✓ サインイン成功（uid: ${user.uid.slice(0,8)}…）`);
      render(true);

      log.push('④ Firestoreへの書き込みを試行中…');
      render(true);
      const testId = 'diag_' + Date.now();
      const writeTimeout = setTimeout(()=>{
        log.push('　→ ✕ タイムアウト（10秒応答なし）。Firestoreデータベースが作成済みか、通信環境をご確認ください。');
        render(false);
      }, 10000);

      this.db.collection('_diagnostics').doc(testId).set({ createdAt: Date.now(), uid: user.uid })
        .then(()=>{
          clearTimeout(writeTimeout);
          log.push('　→ ✓ 書き込み成功');
          render(true);

          log.push('⑤ Firestoreからの読み取りを試行中…');
          render(true);
          return this.db.collection('_diagnostics').doc(testId).get();
        })
        .then((doc)=>{
          if(doc && doc.exists){
            log.push('　→ ✓ 読み取り成功');
          } else {
            log.push('　→ ✕ 書き込んだはずのデータが見つかりません');
          }
          render(true);
          log.push('⑥ 後片付け（テスト用データの削除）中…');
          render(true);
          return this.db.collection('_diagnostics').doc(testId).delete();
        })
        .then(()=>{
          log.push('　→ ✓ 削除成功');
          log.push('');
          log.push('⑦ 「部屋への参加」を模擬テスト中…');
          render(true);
          const roomTestId = 'diagroom_' + Date.now();
          const roomRef = this.db.collection('rooms').doc(roomTestId);
          const joinTimeout = setTimeout(()=>{
            log.push('　→ ✕ タイムアウト（10秒応答なし）。');
            render(false);
          }, 10000);
          // 「誰か他の人」が部屋を作った状況を模して、自分とは異なる仮のhostUidで部屋を作成する
          return roomRef.set({
            hostUid: 'diag-fake-host-uid', guestUid: null, status: 'waiting',
            state: {}, createdAt: Date.now(), updatedAt: Date.now(),
          }).then(()=>{
            // 参加者として、自分のuidをguestUidに書き込めるか（＝実際の「参加する」ボタンと同じ操作）を試す
            return roomRef.update({ guestUid: this.uid, status: 'playing', updatedAt: Date.now() });
          }).then(()=>{
            clearTimeout(joinTimeout);
            log.push('　→ ✓ 参加（guestUidの書き込み）に成功');
            return roomRef.delete();
          }).then(()=>{
            log.push('　→ ✓ 後片付け完了');
            log.push('');
            log.push('✅ すべての診断に成功しました。Firebaseとの接続、および部屋への参加も正常に動作します。');
            render(false);
          }).catch((err)=>{
            clearTimeout(joinTimeout);
            log.push(`　→ ✕ 参加テストに失敗：${err.code || err.message}`);
            if(err.code==='permission-denied'){
              log.push('　　（rooms のセキュリティルールに、参加者による最初の書き込みを許可する条件が含まれていない可能性があります。README.md の最新のルールを貼り付け直してください）');
            }
            roomRef.delete().catch(()=>{});
            render(false);
          });
        })
        .catch((err)=>{
          clearTimeout(writeTimeout);
          log.push(`　→ ✕ 失敗：${err.code || err.message}`);
          if(err.code==='permission-denied'){
            log.push('　　（Firestoreのセキュリティルールが未公開、または内容が正しくない可能性があります）');
          } else if(err.code==='not-found' || err.code==='unavailable'){
            log.push('　　（Firestoreデータベース自体がまだ作成されていない可能性があります）');
          }
          render(false);
        });
    });
  },
};

/* ---------------------------------------------------------------------
 * 4c. チュートリアル（初めての方向けの練習対局ガイド）
 * ------------------------------------------------------------------- */
const Tutorial = {
  active: false,
  shownSteps: null, // Set
  catalogIndex: 0,

  // 練習対局が始まった後に、状況に応じて追加で見せる補足ヒント
  // （カード自体の説明は事前の一覧で済んでいるので、ここでは「操作の仕方」の補足に絞る）
  steps: [
    {
      id: 'choose',
      trigger: (s)=> s.phase==='choose' && !s.players[s.turnIndex].isCPU,
      title: '仮面を選びましょう',
      html: '下段の「あなた」の手札に、仮面が2枚あります。<br><br>1枚をタップして選び、「場に出す」ボタンを押してみましょう。先ほど見た効果一覧を思い出しながら、どちらを出すか考えてみてください。',
    },
    {
      id: 'resolve',
      trigger: (s)=> s.phase==='resolve' && !!s.pendingCard,
      title: '仮面の効果が発動します',
      html: '場に出した仮面の効果です。相手を対象にする効果は、「発動する」ボタンを押すと実際に発動します。<br><br>効果で得た情報（相手の手札の範囲や正体など）は、次以降の駆け引きに活かしましょう。',
    },
    {
      id: 'eliminate',
      trigger: (s)=> s.players.some(p=>!p.alive),
      title: '脱落について',
      html: '手札の数字を言い当てられたり、勝負に負けたりすると脱落します。<br><br>「貴婦人」を出すと、次の自分の番までは他人の効果を受けなくなります。危険を感じたら、貴婦人を手元に残しておくのも有効な戦略です。',
    },
    {
      id: 'gameover',
      trigger: (s)=> !!s.gameOver,
      title: '練習対局、終了です',
      html: 'お疲れ様でした！これでMASQUERADEの基本的な遊び方は身についたはずです。<br><br>タイトル画面に戻って、実際の対局を始めてみましょう。',
      isLast: true,
    },
  ],

  start(){
    this.active = true;
    this.shownSteps = new Set();
    this._savedDifficulty = Game.difficulty; // 元の難易度設定を退避し、チュートリアル終了後に戻す
    Game.mode = 'cpu';
    Game.difficulty = 'novice'; // ここでは保存しない（チュートリアル専用の一時的な変更）
    this.showIntro();
  },

  showIntro(){
    UI.showInfoModal(
      'MASQUERADEへようこそ',
      '仮面舞踏会を舞台にした、1対1の心理戦カードゲームです。<br><br>基本の手札は1枚。自分の番が来たら山札から1枚引いて一時的に2枚になり、そのうち1枚を場に出します。出した仮面の効果が発動し、時には相手を脱落させることもできます。<br><br>最後まで残るか、山札が尽きたときに一番大きい数字の仮面を持っていれば勝利です。<br><br>まずは、10種類の仮面それぞれの効果を順番に見ていきましょう。',
      null, false,
      [
        { label:'仮面の効果を見る', action:()=>{ Tutorial.showCatalogStep(0); } },
        { label:'キャンセル', action:()=>{ UI.forceBackToStart(); } },
      ]
    );
  },

  // 全10種のカードを1枚ずつ、効果とともに紹介していく一覧
  showCatalogStep(index){
    if(index < 0) index = 0;
    if(index >= CARD_ORDER.length){
      this.beginPracticeGame();
      return;
    }
    this.catalogIndex = index;
    const cid = CARD_ORDER[index];
    const d = cardDef(cid);
    const overlay = document.getElementById('info-overlay');
    const box = document.getElementById('info-box');
    const isLastCard = index === CARD_ORDER.length - 1;
    box.innerHTML = `
      <h4>${d.number}. ${d.name}（${d.yomi}）</h4>
      <div class="tutorial-card-preview"><img src="${d.image}" alt="${d.name}"></div>
      <p><b style="color:var(--gold-dim)">【${d.ability}】</b><br>${d.short || d.desc}</p>
      <div class="tutorial-progress">${index+1} / ${CARD_ORDER.length}</div>
      <div class="choice-row">
        ${index>0 ? `<button class="btn" id="tut-prev">前へ</button>` : ''}
        <button class="btn primary" id="tut-next">${isLastCard ? '練習対局へ進む' : '次へ'}</button>
      </div>
      ${!isLastCard ? `<div class="choice-row"><button class="btn ghost" id="tut-skip">スキップして練習対局へ</button></div>` : ''}
      <div class="choice-row"><button class="btn ghost" id="tut-cancel" style="font-size:11px;">やめてタイトルへ戻る</button></div>
    `;
    overlay.classList.add('open');
    if(index>0){
      const prevBtn = document.getElementById('tut-prev');
      if(prevBtn) prevBtn.onclick = ()=>{ Tutorial.showCatalogStep(index-1); };
    }
    document.getElementById('tut-next').onclick = ()=>{ Tutorial.showCatalogStep(index+1); };
    const skipBtn = document.getElementById('tut-skip');
    if(skipBtn) skipBtn.onclick = ()=>{ overlay.classList.remove('open'); Tutorial.beginPracticeGame(); };
    document.getElementById('tut-cancel').onclick = ()=>{ UI.forceBackToStart(); };
  },

  beginPracticeGame(){
    document.getElementById('info-overlay').classList.remove('open');
    Game.newGame();
  },

  end(){
    this.active = false;
    if(this._savedDifficulty){ Game.difficulty = this._savedDifficulty; this._savedDifficulty = null; }
    UI.forceBackToStart();
  },

  checkSteps(){
    if(!this.active || !Game.state) return;
    const s = Game.state;
    for(const step of this.steps){
      if(this.shownSteps.has(step.id)) continue;
      if(step.trigger(s)){
        this.shownSteps.add(step.id);
        if(step.isLast){
          UI.showInfoModal(step.title, step.html, null, false, [
            { label:'タイトルへ戻る', action:()=>{ Tutorial.end(); } },
          ]);
        } else {
          UI.showInfoModal(step.title, step.html, null, true);
        }
        break; // 1回のチェックで表示するのは1ステップのみ
      }
    }
  },
};

/* ---------------------------------------------------------------------
 * 5. UI 描画
 * ------------------------------------------------------------------- */
const UI = {
  selectedCardId: null,

  // ユーザーが入力した文字列（表示名など）をHTMLへ安全に挿入するためのエスケープ処理。
  // 表示名はFirestore経由で他のプレイヤーの画面にも表示されるため、
  // スクリプト注入等を防ぐために必ずこれを通す。
  escapeHtml(str){
    return String(str==null ? '' : str).replace(/[&<>"']/g, (c)=>({
      '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;',
    }[c]));
  },

  init(){
    this.buildRulesPanel();
    this.buildSparkles();
    this.buildCandleGlow();
    this.bindRippleEffect();
    this.buildModePicker();
    this.buildDifficultyPicker();
    this.buildStartDeco();
    this.initSplash();
    this.updateSfxButton();
    this.updateBgmButton();
  },

  toggleSfx(){
    SFX.setEnabled(!SFX.enabled);
    this.updateSfxButton();
    if(SFX.enabled) SFX.click();
  },

  updateSfxButton(){
    const btn = document.getElementById('sfx-toggle');
    if(!btn) return;
    btn.textContent = SFX.enabled ? '🔊' : '🔇';
    btn.classList.toggle('muted', !SFX.enabled);
  },

  toggleBgm(){
    BGM.setEnabled(!BGM.enabled);
    this.updateBgmButton();
  },

  updateBgmButton(){
    const btn = document.getElementById('bgm-toggle');
    if(!btn) return;
    // ミュート状態は「アイコンの見た目を変える」のではなく、.muted クラスの減光表現だけで示す。
    // 特殊なグリフの組み合わせ（結合文字等）は環境によって描画が崩れることがあるため避けている。
    btn.textContent = '🎵';
    btn.classList.toggle('muted', !BGM.enabled);
  },

  // タイトル画面下部の余白を彩る、装飾用の仮面カード（大公・貴婦人）
  buildStartDeco(){
    const el = document.getElementById('start-deco');
    if(!el) return;
    const picks = ['grand_duke', 'noble_lady'];
    el.innerHTML = picks.map((id, i)=>{
      const d = cardDef(id);
      return `<div class="deco-card ${i===0?'a':'b'}"><img src="${d.image}" alt="${d.name}" loading="lazy"></div>`;
    }).join('');
  },

  initSplash(){
    this.buildSplashTitle();
    this.buildSplashParticles();
    this.runSplashProgress();
  },

  // 「MASQUERADE」を1文字ずつ<span>に分解し、順にふわりと浮かび上がらせる
  buildSplashTitle(){
    const el = document.getElementById('splash-title');
    if(!el) return;
    const word = 'MASQUERADE';
    el.innerHTML = word.split('').map((ch, i)=>
      `<span class="sl" style="animation-delay:${(0.25 + i*0.07).toFixed(2)}s">${ch}</span>`
    ).join('');
  },

  // 画面を漂う光の粒を数個だけ生成する（opacity/transformのみ、ぼかしフィルターは使わない）
  buildSplashParticles(){
    const el = document.getElementById('splash-particles');
    if(!el) return;
    const n = 6;
    let html = '';
    for(let i=0;i<n;i++){
      const left = Math.round(Math.random()*90 + 5);
      const size = (Math.random()*2 + 2).toFixed(1);
      const duration = (Math.random()*4 + 6).toFixed(1);
      const delay = (Math.random()*5).toFixed(1);
      html += `<span class="splash-particle" style="left:${left}%; bottom:-4%; width:${size}px; height:${size}px; animation-duration:${duration}s; animation-delay:${delay}s;"></span>`;
    }
    el.innerHTML = html;
  },

  // 支度が整っていく様子を、進捗バーと言葉の移り変わりで演出する
  runSplashProgress(){
    const fill = document.getElementById('splash-progress-fill');
    const sub = document.getElementById('splash-sub');
    const startBtn = document.getElementById('splash-start-btn');
    if(!fill || !sub) return;
    const messages = ['扉の前で支度を整えています', '仮面を選んでいます', '招待状を確かめています', 'さあ、舞踏会へ'];
    let step = 0;
    // 文言はフェードなどの演出を挟まず、そのまま置き換える。
    // （フェード中に前後の文言が視覚的に重なって見える、環境依存の描画不具合を避けるため）
    const setMessage = ()=>{
      sub.textContent = messages[step];
    };
    setMessage();
    // 二重rAFで「0%が確実に1フレーム描画されてから100%へ」変化させる。
    // 単発のrAFだと、特にモバイル端末でスタイル変更がまとめて適用され、
    // 遷移（transition）がアニメーションせずに一瞬で完了扱いになることがあるための対策。
    const raf = (typeof window!=='undefined' && window.requestAnimationFrame) ? window.requestAnimationFrame.bind(window) : (fn)=>setTimeout(fn, 16);
    raf(()=>{ raf(()=>{ if(fill) fill.style.width = '100%'; }); });
    const interval = setInterval(()=>{
      step++;
      if(step >= messages.length){
        clearInterval(interval);
        // 支度が整ったら「はじめる」ボタンを表示する
        if(startBtn) startBtn.classList.add('show');
        return;
      }
      setMessage();
    }, 900);
  },

  dismissSplash(){
    const el = document.getElementById('splash-screen');
    if(el) el.classList.add('dismissed');
    BGM.tryStart(); // ブラウザの自動再生制限のため、最初のユーザー操作（このタップ）に合わせて再生を試みる
  },

  buildDifficultyPicker(){
    const row = document.getElementById('difficulty-row');
    const epithetEl = document.getElementById('difficulty-epithet');
    if(!row) return;
    row.innerHTML = DIFFICULTY_ORDER.map(id=>{
      const d = DIFFICULTY_DEFS[id];
      return `<button class="diff-btn${id===Game.difficulty?' active':''}" data-diff="${id}" onclick="UI.selectDifficulty('${id}')">${d.label}</button>`;
    }).join('');
    if(epithetEl) epithetEl.textContent = DIFFICULTY_DEFS[Game.difficulty].epithet;
    this.renderStatsPanel();
  },

  selectDifficulty(id){
    Game.setDifficulty(id);
    document.querySelectorAll('#difficulty-row .diff-btn').forEach(b=>b.classList.toggle('active', b.dataset.diff===id));
    const epithetEl = document.getElementById('difficulty-epithet');
    if(epithetEl) epithetEl.textContent = DIFFICULTY_DEFS[id].epithet;
    this.renderStatsPanel();
  },

  buildModePicker(){
    const row = document.getElementById('mode-row');
    const epithetEl = document.getElementById('mode-epithet');
    if(!row) return;
    row.innerHTML = MODE_ORDER.map(id=>{
      const d = MODE_DEFS[id];
      return `<button class="diff-btn${id===Game.mode?' active':''}" data-mode="${id}" onclick="UI.selectMode('${id}')">${d.label}</button>`;
    }).join('');
    if(epithetEl) epithetEl.textContent = MODE_DEFS[Game.mode].epithet;
    this.updateModeVisibility();
  },

  selectMode(id){
    Game.setMode(id);
    document.querySelectorAll('#mode-row .diff-btn').forEach(b=>b.classList.toggle('active', b.dataset.mode===id));
    const epithetEl = document.getElementById('mode-epithet');
    if(epithetEl) epithetEl.textContent = MODE_DEFS[id].epithet;
    this.updateModeVisibility();
  },

  updateModeVisibility(){
    const diffWrap = document.getElementById('difficulty-wrap');
    const onlineWrap = document.getElementById('online-wrap');
    const startActions = document.getElementById('start-actions-cpu');
    const isOnline = Game.mode === 'online';
    if(diffWrap) diffWrap.style.display = isOnline ? 'none' : '';
    if(onlineWrap) onlineWrap.style.display = isOnline ? '' : 'none';
    if(startActions) startActions.style.display = isOnline ? 'none' : '';
    if(isOnline) this.renderOnlinePanel();
  },

  // オンライン対戦パネルを、現在の接続状態（Online.panelState）に応じて描画する
  renderOnlinePanel(){
    const el = document.getElementById('online-panel');
    if(!el) return;
    const st = Online.panelState;
    const nameRow = `
      <div class="online-name-row">
        <span>表示名：<b>${UI.escapeHtml(loadPlayerName() || '未設定')}</b></span>
        <button class="btn ghost" style="font-size:11px; padding:5px 10px;" onclick="UI.promptPlayerName()">変更</button>
      </div>
      <div class="online-choice-row" style="margin-bottom:8px;">
        <button class="btn ghost" style="font-size:11px;" onclick="UI.showLeaderboard()">🏆 ランキングを見る</button>
      </div>
    `;
    if(st==='idle'){
      el.innerHTML = nameRow + `
        <div class="online-choice-row">
          <button class="btn primary" onclick="Online.startCreate()">部屋を作る</button>
        </div>
        <div class="online-status-text">合言葉をお持ちの場合はこちらから参加してください</div>
        <div class="online-join-row">
          <input type="text" id="online-code-input" class="online-code-input" placeholder="合言葉" maxlength="6" autocomplete="off" autocapitalize="characters">
          <button class="btn" onclick="Online.startJoin(document.getElementById('online-code-input').value)">参加する</button>
        </div>
      `;
    } else if(st==='creating'){
      el.innerHTML = `<div class="online-status-text">部屋を準備しています<span class="online-waiting-dot"></span><span class="online-waiting-dot"></span><span class="online-waiting-dot"></span></div>`;
    } else if(st==='joining'){
      el.innerHTML = `<div class="online-status-text">部屋に接続しています<span class="online-waiting-dot"></span><span class="online-waiting-dot"></span><span class="online-waiting-dot"></span></div>`;
    } else if(st==='waiting'){
      el.innerHTML = `
        <div class="online-status-text">この合言葉を、対戦相手に伝えてください</div>
        <div class="online-code-display">${Online.roomCode}</div>
        <div class="online-choice-row">
          <button class="btn" onclick="UI.copyRoomCode()">合言葉をコピー</button>
        </div>
        <div class="online-status-text">対戦相手を待っています<span class="online-waiting-dot"></span><span class="online-waiting-dot"></span><span class="online-waiting-dot"></span></div>
        <div class="online-choice-row">
          <button class="btn ghost" onclick="Online.leaveRoom(); Online.resetPanel();">やめる</button>
        </div>
      `;
    } else if(st==='error'){
      el.innerHTML = `
        <div class="online-error">${Online.errorMsg}</div>
        <div class="online-choice-row">
          <button class="btn" onclick="Online.resetPanel()">戻る</button>
        </div>
      `;
    }
  },

  copyRoomCode(){
    if(!Online.roomCode) return;
    if(typeof navigator!=='undefined' && navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(Online.roomCode).then(()=>{
        UI.showToast('合言葉をコピーしました', 'info');
      }).catch(()=>{
        UI.showToast('コピーに対応していない環境です', 'info');
      });
    }
  },

  // オンライン対戦・ランキングで使う表示名を入力してもらう
  promptPlayerName(){
    const overlay = document.getElementById('info-overlay');
    const box = document.getElementById('info-box');
    const current = loadPlayerName();
    box.innerHTML = `
      <h4>表示名を設定</h4>
      <p>オンライン対戦やランキングで使われる名前です（12文字まで）。</p>
      <div class="choice-row">
        <input type="text" id="player-name-input" class="online-code-input" style="text-transform:none; letter-spacing:.05em;" value="${UI.escapeHtml(current)}" maxlength="12" placeholder="仮面卿">
      </div>
      <div class="choice-row" style="margin-top:12px;">
        <button class="btn primary" id="player-name-save">保存</button>
        <button class="btn ghost" id="player-name-cancel">キャンセル</button>
      </div>
    `;
    overlay.classList.add('open');
    const input = document.getElementById('player-name-input');
    document.getElementById('player-name-save').onclick = ()=>{
      const clean = savePlayerName(input.value);
      overlay.classList.remove('open');
      if(Game.state && Game.state.isOnline){
        // 対局中に変更した場合は自分の表示名も更新する
        const myIdx = (typeof Game.state.myIdx==='number') ? Game.state.myIdx : 0;
        Game.state.players[myIdx].name = clean || Game.state.players[myIdx].name;
        UI.render();
      }
      if(document.getElementById('online-panel')) UI.renderOnlinePanel();
      UI.showToast(clean ? `表示名を「${clean}」に設定しました` : '表示名をクリアしました', 'info');
    };
    document.getElementById('player-name-cancel').onclick = ()=>{ overlay.classList.remove('open'); };
  },

  // ランキング（leaderboard）を取得して表示する
  showLeaderboard(){
    const overlay = document.getElementById('info-overlay');
    const box = document.getElementById('info-box');
    box.innerHTML = `
      <h4>🏆 ランキング</h4>
      <div class="online-status-text">読み込み中<span class="online-waiting-dot"></span><span class="online-waiting-dot"></span><span class="online-waiting-dot"></span></div>
      <div class="choice-row" style="margin-top:12px;"><button class="btn" id="leaderboard-close">閉じる</button></div>
    `;
    overlay.classList.add('open');
    document.getElementById('leaderboard-close').onclick = ()=>{ overlay.classList.remove('open'); };

    const renderRows = (rows)=>{
      if(!document.getElementById('leaderboard-close')) return; // 既に閉じられていたら何もしない
      const myUid = Online.uid;
      if(!rows.length){
        box.innerHTML = `
          <h4>🏆 ランキング</h4>
          <p>まだ誰も対局を終えていません。オンライン対戦で最初の記録を作ってみましょう。</p>
          <div class="choice-row" style="margin-top:12px;"><button class="btn" id="leaderboard-close">閉じる</button></div>
        `;
      } else {
        const list = rows.map((r,i)=>{
          const mine = r.uid===myUid;
          return `<div class="leaderboard-row${mine?' mine':''}">
            <span class="lb-rank">${i+1}位</span>
            <span class="lb-name">${UI.escapeHtml(r.name||'名もなき仮面卿')}</span>
            <span class="lb-points">${r.points||0}pt</span>
            <span class="lb-record">${r.wins||0}勝${r.losses||0}敗${r.draws||0}分</span>
            <span class="lb-streak">${r.streak>0 ? `${r.streak}連勝中` : `自己ベスト${r.bestStreak||0}連勝`}</span>
          </div>`;
        }).join('');
        box.innerHTML = `
          <h4>🏆 ランキング</h4>
          <div class="leaderboard-list">${list}</div>
          <div class="choice-row" style="margin-top:12px;"><button class="btn" id="leaderboard-close">閉じる</button></div>
        `;
      }
      document.getElementById('leaderboard-close').onclick = ()=>{ overlay.classList.remove('open'); };
    };

    Online.ensureReady(()=>{
      Online.fetchLeaderboard(30).then(renderRows).catch((err)=>{
        if(!document.getElementById('leaderboard-close')) return;
        box.innerHTML = `
          <h4>🏆 ランキング</h4>
          <p class="online-error">読み込みに失敗しました（${err.code || err.message}）。</p>
          <div class="choice-row" style="margin-top:12px;"><button class="btn" id="leaderboard-close">閉じる</button></div>
        `;
        document.getElementById('leaderboard-close').onclick = ()=>{ overlay.classList.remove('open'); };
      });
    });
  },

  renderStatsPanel(){
    const el = document.getElementById('stats-panel');
    if(!el) return;
    const st = Game.stats[Game.difficulty];
    if(!st || st.played===0){
      el.innerHTML = `<span class="stats-empty">この相手とはまだ対戦していません</span>`;
      return;
    }
    const streakHtml = st.streak>0
      ? `<span class="stats-streak">${st.streak}連勝中</span>`
      : `<span class="stats-streak off">連勝なし</span>`;
    el.innerHTML = `
      <span class="stats-record">${st.wins}勝 ${st.losses}敗 ${st.draws}分</span>
      ${streakHtml}
      <span class="stats-best">自己ベスト ${st.best}連勝</span>
      <button type="button" class="stats-reset-btn" onclick="UI.confirmResetStats()" aria-label="この相手との戦績をリセット">記録をリセット</button>
    `;
  },

  confirmResetStats(){
    const diffLabel = (DIFFICULTY_DEFS[Game.difficulty] || {}).label || '対戦相手';
    UI.showInfoModal(
      '戦績をリセットしますか？',
      `「${diffLabel}」とのこれまでの勝敗数・連勝記録を消去します。<br>この操作は取り消せません。`,
      null, false,
      [
        { label:'リセットする', action:()=>{ Game.resetStats(); UI.showToast('戦績をリセットしました', 'info'); } },
        { label:'やめる', action:()=>{} },
      ]
    );
  },

  buildCandleGlow(){
    const layer = document.getElementById('sparkle-layer');
    if(!layer) return;
    ['a','b','c'].forEach(cls=>{
      const div = document.createElement('div');
      div.className = `candle-glow ${cls}`;
      layer.appendChild(div);
    });
  },

  bindRippleEffect(){
    document.addEventListener('click', (e)=>{
      const btn = e.target.closest('.btn, .btn-grand, .icon-btn, .diff-btn, .fab-discard');
      if(!btn) return;
      if(typeof SFX!=='undefined') SFX.click();
      if(this.reducedMotion()) return;
      if(!btn.classList.contains('btn') && !btn.classList.contains('btn-grand')) return;
      const rect = btn.getBoundingClientRect();
      const ripple = document.createElement('span');
      ripple.className = 'ripple';
      ripple.style.left = (e.clientX - rect.left) + 'px';
      ripple.style.top = (e.clientY - rect.top) + 'px';
      btn.appendChild(ripple);
      setTimeout(()=>ripple.remove(), 650);
    });
  },

  buildSparkles(){
    const layer = document.getElementById('sparkle-layer');
    if(!layer) return;
    let html='';
    for(let i=0;i<26;i++){
      const top = Math.random()*100, left = Math.random()*100, delay = Math.random()*6;
      html += `<div class="sparkle" style="top:${top}%; left:${left}%; animation-delay:${delay}s;"></div>`;
    }
    layer.innerHTML = html;
  },

  rulesHtml(){
    let rows = '';
    CARD_ORDER.forEach(id=>{
      const d = cardDef(id);
      rows += `<div class="rule-card-row">
        <div class="rule-thumb"><img src="${d.image}" alt="${d.name}" loading="lazy"></div>
        <div class="rule-text">
          <span class="rn">${d.number}. ${d.name}</span><span class="ry">（${d.yomi}）</span><span class="rability">【${d.ability}】</span>
          <div class="rd">${d.desc}</div>
        </div>
        <div class="rule-count">×${d.count}</div>
      </div>`;
    });
    return `${rows}
      <div class="rd" style="margin:14px 0 6px; opacity:.85;">
        数字が小さいほど「攻めの読み合い」向き。数字が大きいほど希少で、抱え続ける価値と危険の両方を持つ切り札です。
      </div>
      <div class="rd" style="margin:10px 0 6px; opacity:.85;">
        <b style="color:var(--gold-light);">MASQUERADEの黄金律</b>：カードの効果が発動するのは、自分の番に自分でその仮面を場に出した時のみ。他人の効果で捨てさせられた場合や、山札切れによる最後の公開では、効果は発動しません（ただし「仮面の主催者」の脱落だけは、捨てさせられた場合にも発動する唯一の例外です）。
      </div>
      <div class="rd" style="margin:10px 0 6px; opacity:.85;">
        自分と対戦相手は、それぞれ独立した山札（同じ構成・別々のシャッフル）を使います。
      </div>
      <div class="rd" style="margin:10px 0 6px; opacity:.85;">
        カードの情報を探るため、対戦相手への簡単な質問も自由です。より高度な心理戦をお楽しみください。
      </div>`;
  },

  buildRulesPanel(){
    const panel = document.getElementById('rules-panel');
    if(!panel) return;
    panel.innerHTML = `<h3>仮面一覧（全18枚）</h3>${this.rulesHtml()}`;
  },

  showHelpModal(){
    const overlay = document.getElementById('help-overlay');
    const box = document.getElementById('help-box');
    if(!overlay || !box) return;
    box.innerHTML = `
      <button class="help-close" onclick="UI.closeHelpModal()" aria-label="閉じる">×</button>
      <h3>仮面一覧とルール</h3>
      ${this.rulesHtml()}
    `;
    overlay.classList.add('open');
  },

  closeHelpModal(){
    const overlay = document.getElementById('help-overlay');
    if(overlay) overlay.classList.remove('open');
  },

  toggleRules(){
    const panel = document.getElementById('rules-panel');
    const btn = document.getElementById('rules-toggle-btn');
    const open = panel.classList.toggle('open');
    btn.textContent = (open?'▴':'▾') + ' 仮面の一覧とルールを見る';
  },

  toggleLog(){
    const panel = document.getElementById('log-panel');
    const open = panel.classList.toggle('open');
    if(open) this.renderLog();
  },

  showTable(){
    document.getElementById('start-screen').style.display = 'none';
    document.getElementById('table').classList.add('open');
    document.body.classList.add('table-mode');
    const header = document.getElementById('site-header');
    if(header) header.classList.add('compact');
  },

  backToStart(){
    const s = Game.state;
    if(s && !s.gameOver){
      const oppName = Game.opp() ? Game.opp().name : '相手';
      const msg = `対戦は進行中です。<br>投了すると${oppName}の勝利として記録されます。`;
      UI.showInfoModal(
        '対戦を中断しますか？',
        msg,
        null, false,
        [
          { label:'ゲーム続行', action:()=>{} },
          { label:'タイトルに戻る', action:()=>{ UI.forceBackToStart(); } },
          { label:'リタイア', action:()=>{ Game.concede(); } },
        ]
      );
      return;
    }
    UI.forceBackToStart();
  },

  forceBackToStart(){
    document.getElementById('info-overlay').classList.remove('open');
    document.getElementById('gameover-overlay').classList.remove('open');
    document.getElementById('discard-overlay').classList.remove('open');
    document.getElementById('log-panel').classList.remove('open');
    document.getElementById('table').classList.remove('open');
    document.getElementById('start-screen').style.display = '';
    document.body.classList.remove('table-mode');
    const header = document.getElementById('site-header');
    if(header) header.classList.remove('compact');
    if(Game.state && Game.state.isOnline && typeof Online!=='undefined' && Online.leaveRoom) Online.leaveRoom();
    this.hideOpponentStaleWarning();
    this._leftNoticeShown = false;
    // チュートリアル中にどの経路で戻ってきても、必ず後片付け（元の難易度設定への復元など）を行う
    if(typeof Tutorial!=='undefined' && Tutorial.active){
      Tutorial.active = false;
      if(Tutorial._savedDifficulty){ Game.difficulty = Tutorial._savedDifficulty; Tutorial._savedDifficulty = null; }
    }
    Game.state = null;
  },

  cardInline(cid){
    const d = cardDef(cid);
    return `<span style="display:inline-flex;align-items:center;gap:8px;vertical-align:middle;">
      <img class="card-inline-img" src="${d.image}" alt="${d.name}" style="width:34px;aspect-ratio:300/505;object-fit:cover;border-radius:5px;box-shadow:0 2px 6px rgba(0,0,0,0.5);">
      <b>${d.name}（${d.number}）</b>
    </span>`;
  },

  render(){
    if(!Game.state) return;
    const s = Game.state;
    // CPU戦・オンライン対戦ともに、常に自分の枠（myIdx）が下段、相手が上段になる。
    const bottomIdx = (typeof s.myIdx==='number') ? s.myIdx : 0;
    const topIdx = Game.other(bottomIdx);
    const bottomPlayer = s.players[bottomIdx];
    const topPlayer = s.players[topIdx];

    document.getElementById('turn-badge').textContent =
      s.gameOver ? '舞踏会、終幕' : `第${s.turnCount}巡・${s.players[s.turnIndex].name}の番`;
    const quickChatBtn = document.getElementById('quick-chat-btn');
    if(quickChatBtn) quickChatBtn.style.display = (s.isOnline && !s.gameOver) ? '' : 'none';

    // 上段（対戦相手）
    document.getElementById('opp-name').textContent = topPlayer.name;
    document.getElementById('opp-deck-count-text').textContent = s.decks[topIdx].length;
    document.getElementById('opp-protect').classList.toggle('show', topPlayer.protectedFlag);
    document.getElementById('opp-eliminated').classList.toggle('show', !topPlayer.alive);
    const oppThinking = !s.gameOver && (s.phase==='choose' || s.phase==='resolve') &&
      (topPlayer.isCPU || (s.isOnline && topIdx===s.turnIndex));
    document.getElementById('opp-hand').innerHTML = topPlayer.hand.map(()=>
      `<div class="card-back${oppThinking?' thinking':''}"><span class="mask-icon">🎭</span></div>`).join('');
    const oppZoneLabel = document.getElementById('opp-zone-label');
    if(oppZoneLabel) oppZoneLabel.textContent = '対戦相手';

    // 下段（あなた）
    document.getElementById('me-name').textContent = bottomPlayer.name;
    document.getElementById('me-deck-count-text').textContent = s.decks[bottomIdx].length;
    document.getElementById('me-protect').classList.toggle('show', bottomPlayer.protectedFlag);
    document.getElementById('me-eliminated').classList.toggle('show', !bottomPlayer.alive);
    const meCanChoose = !s.gameOver && s.phase==='choose' && !bottomPlayer.isCPU && bottomIdx===s.turnIndex;
    if(!meCanChoose) this.selectedCardId = null; // 自分の選択フェーズ以外では選択状態を破棄
    // 選択待ちのこの瞬間だけ、引いたばかりの1枚に特別な登場演出を付ける
    const justDrawnId = (meCanChoose && s.lastDrawnCardId) ? s.lastDrawnCardId : null;
    document.getElementById('me-hand').innerHTML = bottomPlayer.hand.map((cid,i)=>this.renderCard(cid,{
      selectable: meCanChoose,
      chosen: cid===this.selectedCardId,
      justDrawn: cid===justDrawnId,
      onclick: `UI.onMeSelectCard('${cid}')`,
    })).join('');
    const meZoneLabel = document.getElementById('me-zone-label');
    if(meZoneLabel) meZoneLabel.textContent = 'あなた';

    this.renderActionPanel();
    if(document.getElementById('log-panel').classList.contains('open')) this.renderLog();
    if(document.getElementById('discard-overlay').classList.contains('open')) this.showDiscardModal();

    // オンライン対戦：自分の操作による変化だけをFirestoreへ書き戻す（受信した更新の反映では書き戻さない）
    if(s.isOnline && !Game._applyingRemote && typeof Online!=='undefined' && Online.scheduleSync){
      Online.scheduleSync();
    }

    // チュートリアル進行中は、状況に応じたヒントを表示する
    if(typeof Tutorial!=='undefined' && Tutorial.active){
      Tutorial.checkSteps();
    }
  },

  renderCard(cid, opts){
    opts = opts || {};
    const d = cardDef(cid);
    const cls = ['card'];
    if(opts.selectable) cls.push('selectable');
    if(opts.chosen) cls.push('chosen');
    if(opts.justDrawn) cls.push('card-drawn');
    return `<div class="${cls.join(' ')}" data-cid="${cid}" ${opts.selectable?`onclick="${opts.onclick}"`:''} title="${d.name}（${d.number}）">
      <img src="${d.image}" alt="${d.name}（${d.number}）">
    </div>`;
  },

  renderDiscardChips(discardArr){
    if(!discardArr.length) return `<span class="chip empty" style="opacity:.5;">まだ何も出ていない</span>`;
    return discardArr.map(cid=>{
      const d = cardDef(cid);
      return `<span class="chip ${d.exposeEliminates?'host':''}" title="${d.name}（${d.number}）">
        <img src="${d.image}" alt="${d.name}">
        <b>${d.number}</b> ${d.name}
      </span>`;
    }).join('');
  },

  showDiscardModal(){
    const overlay = document.getElementById('discard-overlay');
    const box = document.getElementById('discard-box');
    if(!overlay || !box) return;
    const s = Game.state;
    if(!s) return;
    const me = Game.me(), opp = Game.opp();
    box.innerHTML = `
      <button class="help-close" onclick="UI.closeDiscardModal()" aria-label="閉じる">×</button>
      <h3>これまでに場に出された仮面</h3>
      <div class="discard-modal-section">
        <h5>${me.name}</h5>
        <div class="discard-strip">${this.renderDiscardChips(me.discard)}</div>
      </div>
      <div class="discard-modal-section">
        <h5>${opp.name}</h5>
        <div class="discard-strip">${this.renderDiscardChips(opp.discard)}</div>
      </div>
    `;
    overlay.classList.add('open');
  },

  closeDiscardModal(){
    const overlay = document.getElementById('discard-overlay');
    if(overlay) overlay.classList.remove('open');
  },

  renderLog(){
    const panel = document.getElementById('log-panel');
    const s = Game.state;
    if(!s) return;
    const lines = s.log.map(l=> l.header ? `<div class="lg-turn">${l.text}</div>` : `<div>${l.text}</div>`).join('');
    panel.innerHTML = `<button class="lg-handle" onclick="UI.toggleLog()" aria-label="閉じる"></button><button class="lg-close-x" onclick="UI.toggleLog()" aria-label="閉じる">×</button>${lines}`;
    panel.scrollTop = panel.scrollHeight;
  },

  renderActionPanel(){
    const s = Game.state;
    const box = document.getElementById('ap-prompt');
    const panel = document.getElementById('action-panel');

    if(s.gameOver){
      box.innerHTML = '結果は下の画面をご覧ください。';
      panel.querySelectorAll('.choice-row, .num-pad, .sub').forEach(n=>n.remove());
      return;
    }

    // 既存の動的要素を除去してから作り直す
    panel.querySelectorAll('.choice-row, .num-pad, .sub, .card').forEach(n=>n.remove());

    if(s.phase==='resolve' && s.pendingCard){
      const cid = s.pendingCard;
      const d = cardDef(cid);
      const activeIdx = s.turnIndex;
      const targetIdx = Game.other(activeIdx);
      // actorIsMe: 今の手番のプレイヤーが、この端末で操作している「自分（myIdx）」かどうか
      // CPU戦では自分の番（myIdx=0）の時だけ true。オンライン対戦では自分の枠の番の時だけ true になる。
      const myIdx = (typeof s.myIdx==='number') ? s.myIdx : 0;
      const actorIsMe = !s.players[activeIdx].isCPU && activeIdx===myIdx;
      if(!actorIsMe){
        box.innerHTML = `${s.players[activeIdx].name}が「${d.name}」の力を発動している…`;
        return;
      }
      if(d.effect==='guessRank'){
        box.innerHTML = `「${d.name}」発動：${s.players[targetIdx].name}の手札の数字を宣言してください`;
        const pad = document.createElement('div');
        pad.className = 'num-pad';
        for(let n=1;n<=10;n++){
          const b = document.createElement('button');
          b.className='btn'; b.textContent=n;
          b.onclick = ()=>Game.effGuessRank(activeIdx, n);
          pad.appendChild(b);
        }
        panel.appendChild(pad);
        return;
      }
      // 自分専用の情報効果は、自動的に発動して結果モーダルを開く（確認クリックを挟まない）
      if(d.effect==='peekDeckTop'){
        box.innerHTML = `「${d.name}」発動中…`;
        Game.effPeekDeckTop(activeIdx);
        return;
      }
      if(d.effect==='protectSelf'){
        box.innerHTML = `「${d.name}」の加護を求めます。`;
        const row = document.createElement('div');
        row.className='choice-row';
        const b = document.createElement('button');
        b.className='btn primary'; b.textContent='発動する';
        b.onclick = ()=>Game.effProtectSelf(activeIdx);
        row.appendChild(b);
        panel.appendChild(row);
        return;
      }
      if(['peekRange','doubleRedraw','secretRedraw','compareHand','revealHand','sealTurn'].includes(d.effect)){
        box.innerHTML = `「${d.name}」の力を${s.players[targetIdx].name}に対して発動します。`;
        const row = document.createElement('div');
        row.className='choice-row';
        const b = document.createElement('button');
        b.className='btn primary'; b.textContent='発動する';
        b.onclick = ()=>{
          if(d.effect==='peekRange') Game.effPeekRange(activeIdx);
          else if(d.effect==='doubleRedraw') Game.effDoubleRedraw(activeIdx);
          else if(d.effect==='secretRedraw') Game.effSecretRedraw(activeIdx);
          else if(d.effect==='compareHand') Game.effCompareHand(activeIdx);
          else if(d.effect==='revealHand') Game.effRevealHand(activeIdx);
          else if(d.effect==='sealTurn') Game.effSealTurn(activeIdx);
        };
        row.appendChild(b);
        panel.appendChild(row);
        return;
      }
    }

    if(s.phase==='choose'){
      const myIdxC = (typeof s.myIdx==='number') ? s.myIdx : 0;
      const activeIsHuman = !s.players[s.turnIndex].isCPU && s.turnIndex===myIdxC;
      if(activeIsHuman){
        if(this.selectedCardId){
          const d = cardDef(this.selectedCardId);
          box.innerHTML = `「${d.name}（${d.number}）」の【${d.ability}】を場に出しますか？<br><span class="sub-desc">${d.short || d.desc}</span>`;
          const row = document.createElement('div');
          row.className = 'choice-row';
          const okBtn = document.createElement('button');
          okBtn.className = 'btn primary'; okBtn.textContent = 'この仮面を場に出す';
          okBtn.onclick = () => this.confirmPlaySelected();
          const cancelBtn = document.createElement('button');
          cancelBtn.className = 'btn ghost'; cancelBtn.textContent = 'やめる';
          cancelBtn.onclick = () => this.cancelSelection();
          row.appendChild(okBtn); row.appendChild(cancelBtn);
          panel.appendChild(row);
        } else {
          box.innerHTML = 'どちらの仮面を場に出しますか？（手札から1枚を選んでください）';
        }
      } else {
        box.innerHTML = `${s.players[s.turnIndex].name}が思案している…`;
      }
      return;
    }

    box.innerHTML = '―';
  },

  onMeSelectCard(cid){
    const s = Game.state;
    if(!s || s.phase!=='choose') return;
    const myIdx = (typeof s.myIdx==='number') ? s.myIdx : 0;
    if(s.players[s.turnIndex].isCPU || s.turnIndex!==myIdx) return;
    this.selectedCardId = (this.selectedCardId===cid) ? null : cid;
    // クリックした瞬間に、押し込むような手応えのある小さな弾みを一度だけ加える
    if(!this.reducedMotion()){
      const el = document.querySelector(`#me-hand .card[data-cid="${cid}"]`);
      if(el){
        el.classList.remove('select-pulse');
        void el.offsetWidth; // reflowでアニメーションを再トリガーする
        el.classList.add('select-pulse');
      }
    }
    this.render();
  },

  cancelSelection(){
    this.selectedCardId = null;
    this.render();
  },

  confirmPlaySelected(){
    const cid = this.selectedCardId;
    if(!cid) return;
    const s = Game.state;
    if(!s || s.phase!=='choose') return;
    const myIdx = (typeof s.myIdx==='number') ? s.myIdx : 0;
    if(s.players[s.turnIndex].isCPU || s.turnIndex!==myIdx) return;
    const activeIdx = s.turnIndex;
    this.selectedCardId = null;
    const el = document.querySelector(`#me-hand .card[data-cid="${cid}"]`);
    if(el && !this.reducedMotion()){
      // 選択不可にして二重クリックを防ぐ
      document.querySelectorAll('#me-hand .card.selectable').forEach(c=>{ c.classList.remove('selectable'); c.onclick=null; });
      this.flyCardToDiscard(el, 'fab-discard');
      setTimeout(()=>Game.discardCard(activeIdx, cid), 380);
    } else {
      Game.discardCard(activeIdx, cid);
    }
  },

  reducedMotion(){
    return typeof window!=='undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  },

  flyCardToDiscard(el, targetId){
    const rect = el.getBoundingClientRect();
    const targetEl = document.getElementById(targetId);
    if(!targetEl){ return; }
    const trect = targetEl.getBoundingClientRect();
    const clone = el.cloneNode(true);
    clone.classList.add('flying-card');
    clone.classList.remove('selectable');
    clone.style.left = rect.left+'px';
    clone.style.top = rect.top+'px';
    clone.style.width = rect.width+'px';
    clone.style.height = rect.height+'px';
    clone.style.margin = '0';
    document.body.appendChild(clone);
    el.style.visibility = 'hidden';

    const raf = (typeof window!=='undefined' && window.requestAnimationFrame) ? window.requestAnimationFrame.bind(window) : (fn)=>setTimeout(fn, 16);
    raf(()=>{
      const dx = (trect.left + Math.min(trect.width,40)/2) - (rect.left + rect.width/2);
      const dy = (trect.top + trect.height/2) - (rect.top + rect.height/2);
      clone.classList.add('flying'); // 飛んでいる間だけ、金色の光の尾を引かせる
      clone.style.transform = `translate(${dx}px, ${dy}px) rotate(340deg) scale(0.45)`;
      clone.style.opacity = '0.2';
    });
    setTimeout(()=>{ clone.remove(); }, 520);
  },

  showTurnBanner(text){
    if(typeof SFX!=='undefined') SFX.turn();
    if(this.reducedMotion()) return;
    const el = document.createElement('div');
    el.className = 'turn-banner';
    el.textContent = text;
    document.body.appendChild(el);
    setTimeout(()=>el.remove(), 1750);
  },

  showToast(text, kind, duration){
    kind = kind || 'info';
    duration = duration || 2200;
    const el = document.createElement('div');
    el.className = `turn-banner toast ${kind}`;
    el.textContent = text;
    document.body.appendChild(el);
    if(this.reducedMotion()){
      el.style.animation = 'none';
      el.style.opacity = '1';
      el.style.transform = 'translate(-50%,0)';
    }
    setTimeout(()=>el.remove(), duration);
  },

  // カード効果ごとの短い演出（effect-stage）を再生する。結果を伝えるモーダルの表示タイミングは
  // 一切変えず（＝文字表示はこれまで通り）、この演出はあくまで「前振り」として並行して流れる。
  // 操作を妨げないよう pointer-events:none を貫通させているため、いつでもボタン操作は可能。
  playEffectStage(key){
    const def = EFFECT_STAGE_DEFS[key];
    const stage = document.getElementById('effect-stage');
    if(!def || !stage) return;
    if(this.reducedMotion()) return; // 演出を減らす設定の場合は、結果モーダルの表示だけで十分伝わるようにする

    // 前の演出がまだ終わっていない場合に備えて一旦リセットする
    stage.className = 'effect-stage';
    stage.style.setProperty('--stage-color', def.color);
    const iconEl = document.getElementById('effect-stage-icon');
    const labelEl = document.getElementById('effect-stage-label');
    if(iconEl) iconEl.textContent = def.icon;
    if(labelEl) labelEl.textContent = def.label;

    // 光の粒を放射状にランダム散布する
    const particlesEl = document.getElementById('effect-stage-particles');
    if(particlesEl){
      let html = '';
      const n = 10;
      for(let i=0;i<n;i++){
        const angle = (Math.PI*2*i/n) + (Math.random()*0.5 - 0.25);
        const dist = 70 + Math.random()*60;
        const px = Math.cos(angle)*dist;
        const py = Math.sin(angle)*dist;
        const delay = (Math.random()*0.15).toFixed(2);
        html += `<span class="effect-stage-particle" style="left:50%; top:42%; --px:${px.toFixed(0)}px; --py:${py.toFixed(0)}px; animation-delay:${delay}s;"></span>`;
      }
      particlesEl.innerHTML = html;
    }

    // 1フレーム待ってからクラスを付け直すことで、アニメーションが確実に最初から再生されるようにする
    const raf = (typeof window!=='undefined' && window.requestAnimationFrame) ? window.requestAnimationFrame.bind(window) : (fn)=>setTimeout(fn,16);
    raf(()=>{ raf(()=>{ stage.classList.add('open', `fx-${key}`); }); });

    clearTimeout(this._stageTimer);
    this._stageTimer = setTimeout(()=>{
      stage.classList.remove('open', `fx-${key}`);
    }, 2000);
  },

  // 対戦相手から届いた簡易メッセージを吹き出し風に表示する
  showChatBubble(text){
    const s = Game.state;
    const oppName = (s && s.myIdx!==undefined) ? s.players[Game.other(s.myIdx)].name : '対戦相手';
    this.showToast(`💬 ${oppName}「${text}」`, 'info', 3600);
    if(typeof SFX!=='undefined') SFX.turn();
  },

  // 対戦相手からの反応が一定時間なくなった時に表示する、控えめな警告バナー
  // （対局操作自体は妨げず、いつでも消して普通に続けられるようにしている）
  showOpponentStaleWarning(){
    const banner = document.getElementById('stale-banner');
    if(banner) banner.style.display = '';
  },

  hideOpponentStaleWarning(){
    const banner = document.getElementById('stale-banner');
    if(banner) banner.style.display = 'none';
  },

  confirmLeaveStale(){
    UI.showInfoModal(
      '対局を終了しますか？',
      '対戦相手からの反応がありません。対局を終了してタイトルへ戻りますか？',
      null, false,
      [
        { label:'終了する', action:()=>{ UI.forceBackToStart(); } },
        { label:'もう少し待つ', action:()=>{} },
      ]
    );
  },

  // 対戦相手が自ら退出したことが分かった場合に表示する（反応なしの推測ではなく確定情報のため、
  // ワンクッション挟まずすぐに知らせる）
  showOpponentLeftNotice(){
    if(this._leftNoticeShown) return;
    this._leftNoticeShown = true;
    if(typeof Online!=='undefined') Online.stopHeartbeat();
    UI.showInfoModal(
      '対戦相手が退出しました',
      '対戦相手が舞踏会を去りました。この対局は終了します。',
      null, false,
      [ { label:'タイトルへ戻る', action:()=>{ UI._leftNoticeShown = false; UI.forceBackToStart(); } } ]
    );
  },

  // 定型文の一覧から選んで相手に送る、簡易チャットの選択画面を開く
  showQuickChatPicker(){
    if(!Game.state || !Game.state.isOnline) return;
    const overlay = document.getElementById('info-overlay');
    const box = document.getElementById('info-box');
    box.innerHTML = `
      <h4>簡単な質問を送る</h4>
      <p>対戦相手に送る一言を選んでください。</p>
      <div class="quick-chat-list" id="quick-chat-list">
        ${QUICK_CHAT_PHRASES.map((text,i)=>`<button class="quick-chat-btn" data-qc="${i}">${text}</button>`).join('')}
      </div>
      <div class="choice-row"><button class="btn" id="quick-chat-cancel">キャンセル</button></div>
    `;
    overlay.classList.add('open');
    QUICK_CHAT_PHRASES.forEach((text,i)=>{
      box.querySelector(`[data-qc="${i}"]`).onclick = ()=>{
        overlay.classList.remove('open');
        Online.sendChat(text);
        this.showToast(`💬 あなた「${text}」`, 'info', 2200);
      };
    });
    document.getElementById('quick-chat-cancel').onclick = ()=>{ overlay.classList.remove('open'); };
  },

  flashEliminated(playerIdx){
    const zoneId = playerIdx===0 ? 'player-zone' : 'opponent-zone';
    const zone = document.getElementById(zoneId);
    if(!zone) return;
    zone.classList.remove('elim-flash');
    void zone.offsetWidth; // reflow でアニメーションを再トリガー
    zone.classList.add('elim-flash');
    setTimeout(()=>zone.classList.remove('elim-flash'), 750);
  },

  spawnBurstParticles(container, palette){
    if(this.reducedMotion() || !container) return;
    const colors = palette || ['var(--gold-light)','var(--gold)','var(--royal)'];
    for(let i=0;i<26;i++){
      const p = document.createElement('span');
      p.className = 'burst-particle';
      const angle = Math.random()*Math.PI*2;
      const dist = 60 + Math.random()*120;
      p.style.setProperty('--tx', `${Math.cos(angle)*dist}px`);
      p.style.setProperty('--ty', `${Math.sin(angle)*dist}px`);
      p.style.background = colors[Math.floor(Math.random()*colors.length)];
      p.style.animationDelay = `${Math.random()*0.15}s`;
      container.appendChild(p);
      setTimeout(()=>p.remove(), 1300);
    }
  },

  showInfoModal(title, html, onClose, showCloseBtn, customButtons){
    const overlay = document.getElementById('info-overlay');
    const box = document.getElementById('info-box');
    let btnHtml = '';
    if(customButtons){
      btnHtml = `<div class="choice-row">${customButtons.map((b,i)=>`<button class="btn ${i===0?'primary':''}" data-cb="${i}">${b.label}</button>`).join('')}</div>`;
    } else if(showCloseBtn){
      btnHtml = `<div class="choice-row"><button class="btn primary" id="info-ok-btn">わかった</button></div>`;
    }
    box.innerHTML = `<h4>${title}</h4><p>${html}</p>${btnHtml}`;
    overlay.classList.add('open');
    if(customButtons){
      customButtons.forEach((b,i)=>{
        box.querySelector(`[data-cb="${i}"]`).onclick = ()=>{
          overlay.classList.remove('open');
          b.action();
        };
      });
    } else {
      const okBtn = document.getElementById('info-ok-btn');
      if(okBtn){
        okBtn.onclick = ()=>{ overlay.classList.remove('open'); if(onClose) onClose(); };
      } else if(onClose){
        // ボタンが無い呼び出しのフォールバック：オーバーレイを確実に閉じてから続行する
        overlay.classList.remove('open');
        onClose();
      }
    }
  },

  showGameOver(){
    const s = Game.state;
    // 自分の操作で決着した場合も、相手の操作で決着した場合も、この時点で「表示済み」としておく。
    // これにより、オンライン対戦で自分が起こした更新が自分自身に同期で返ってきた際に、
    // 決着モーダルが二重に表示されるのを防ぐ。
    if(typeof Online!=='undefined') Online._gameOverShown = true;
    const overlay = document.getElementById('gameover-overlay');
    const box = document.getElementById('gameover-box');
    const myIdx = (typeof s.myIdx==='number') ? s.myIdx : 0;
    let title, sub, palette;
    if(s.isOnline){
      if(s.winner){
        const iWon = s.winner.id===myIdx;
        title = `${s.winner.name}の勝利`;
        sub = s.endReason==='concede' ? `${s.players[Game.other(s.winner.id)].name}が投了した。` : '正体を見破られ、退場となった。';
        palette = iWon ? ['var(--gold-light)','var(--gold)','var(--royal)'] : ['var(--velvet-light)','var(--danger)','var(--gold-dim)'];
        if(typeof SFX!=='undefined'){ iWon ? SFX.win() : SFX.lose(); }
      } else {
        title='引き分け'; sub='舞踏会は決着つかず幕を閉じた。'; palette=['var(--silver)','var(--ivory-dim)','var(--gold-dim)'];
      }
    } else if(s.winner && s.winner.id===myIdx){ title='あなたの勝利'; sub='正体を隠し通し、王位を継承した。'; palette=['var(--gold-light)','var(--gold)','var(--royal)']; if(typeof SFX!=='undefined') SFX.win(); }
    else if(s.winner && s.winner.id===Game.other(myIdx)){
      title=`${s.players[Game.other(myIdx)].name}の勝利`;
      sub = s.endReason==='concede' ? 'あなたは投了した。' : 'あなたの正体は見破られてしまった。';
      palette=['var(--velvet-light)','var(--danger)','var(--gold-dim)']; if(typeof SFX!=='undefined') SFX.lose();
    }
    else { title='引き分け'; sub='舞踏会は決着つかず幕を閉じた。'; palette=['var(--silver)','var(--ivory-dim)','var(--gold-dim)']; }

    const revealRow = s.players.map(p=>{
      const cid = p.hand[0];
      return `<div class="reveal-row" style="display:flex;justify-content:space-between;align-items:center;font-size:12.5px;padding:6px 0;border-top:1px dashed rgba(255,255,255,0.1);">
        <span>${p.name}</span><span>${cid ? UI.cardInline(cid) : (p.alive?'—':'退場')}</span>
      </div>`;
    }).join('');

    let streakLine = '', recordLine = '';
    if(!s.isOnline){
      const st = Game.stats[Game.difficulty] || { streak:0, best:0, wins:0, losses:0, draws:0 };
      if(s.winner && s.winner.id===myIdx && st.streak>0){
        streakLine = `<div class="result-streak win">${st.streak}連勝中！（自己ベスト ${st.best}連勝）</div>`;
      } else if(s.winner && s.winner.id===Game.other(myIdx)){
        streakLine = st.best>0
          ? `<div class="result-streak lose">連勝はここで途切れた（自己ベスト ${st.best}連勝）</div>`
          : '';
      }
      recordLine = `<div class="result-record">通算 ${st.wins}勝 ${st.losses}敗 ${st.draws}分</div>`;
    }

    box.innerHTML = `
      <div class="result-title">${title}</div>
      <div class="result-sub">${sub}</div>
      ${streakLine}
      ${revealRow}
      ${recordLine}
      <div class="start-actions" style="margin-top:18px;">
        <button class="btn-grand" onclick="UI.restart()">もう一度舞踏会へ</button>
      </div>
      <div class="start-actions" style="margin-top:10px;">
        <button class="btn ghost" onclick="UI.forceBackToStart()">タイトルに戻る</button>
      </div>
      <div class="start-actions" style="margin-top:10px;">
        <button class="btn ghost" onclick="UI.shareResult()">結果を共有</button>
      </div>
    `;
    overlay.classList.add('open');
    this.spawnBurstParticles(box, palette);
  },

  shareResult(){
    const s = Game.state;
    if(!s) return;
    const myIdx = (typeof s.myIdx==='number') ? s.myIdx : 0;
    let text;
    if(s.isOnline){
      text = s.winner
        ? (s.winner.id===myIdx
            ? `MASQUERADE ―仮面領の一夜― でオンライン対戦に勝利しました🎭`
            : `MASQUERADE ―仮面領の一夜― でオンライン対戦に挑戦中🎭 正体を隠し通せるか…？`)
        : `MASQUERADE ―仮面領の一夜― は引き分けに終わりました🎭`;
    } else {
      const st = Game.stats[Game.difficulty] || { streak:0, best:0 };
      if(s.winner && s.winner.id===myIdx){
        text = st.streak>1
          ? `MASQUERADE ―仮面領の一夜― で${st.streak}連勝中🎭 正体を隠し通せるか、挑んでみませんか？`
          : `MASQUERADE ―仮面領の一夜― で勝利しました🎭`;
      } else if(s.winner && s.winner.id===Game.other(myIdx)){
        text = `MASQUERADE ―仮面領の一夜― に挑戦中🎭 正体を隠し通せるか…？`;
      } else {
        text = `MASQUERADE ―仮面領の一夜― で引き分けに終わりました🎭`;
      }
    }
    if(typeof navigator!=='undefined' && navigator.share){
      navigator.share({ title:'MASQUERADE', text }).catch(()=>{});
    } else if(typeof navigator!=='undefined' && navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(text).then(()=>{
        UI.showToast('結果をコピーしました', 'info');
      }).catch(()=>{
        UI.showToast('共有に対応していない環境です', 'info');
      });
    } else {
      UI.showToast('共有に対応していない環境です', 'info');
    }
  },

  // タイトル画面からの開始：いきなり対局が始まらないよう、一度確認を挟む
  confirmStartGame(){
    BGM.tryStart(); // スプラッシュでの自動再生がブロックされていた場合の保険として、ここでも再試行する
    const diff = DIFFICULTY_DEFS[Game.difficulty] || DIFFICULTY_DEFS.courtier;
    UI.showInfoModal(
      '準備はよろしいですか？',
      `「${diff.label}」との対局が始まります。<br>基本の手札は1枚。自分の番には山札から引いて2枚になり、そのうち1枚を場に出して駆け引きを進めましょう。`,
      null, false,
      [
        { label:'舞踏会へ', action:()=>{ Game.newGame(); } },
        { label:'キャンセル', action:()=>{} },
      ]
    );
  },

  restart(){
    document.getElementById('gameover-overlay').classList.remove('open');
    const s = Game.state;
    if(s && s.isOnline){
      UI.showInfoModal(
        'もう一度、舞踏会へ',
        '同じ相手と、もう一度対局しますか？（相手の画面にも自動で反映されます）',
        null, false,
        [
          { label:'はじめる', action:()=>{ Online.rematch(); } },
          { label:'キャンセル', action:()=>{ document.getElementById('gameover-overlay').classList.add('open'); } },
        ]
      );
      return;
    }
    const diff = DIFFICULTY_DEFS[Game.difficulty] || DIFFICULTY_DEFS.courtier;
    UI.showInfoModal(
      'もう一度、舞踏会へ',
      `同じ相手（「${diff.label}」）と、もう一度対局しますか？`,
      null, false,
      [
        { label:'はじめる', action:()=>{ Game.newGame(); } },
        { label:'キャンセル', action:()=>{ document.getElementById('gameover-overlay').classList.add('open'); } },
      ]
    );
  },
};

document.addEventListener('DOMContentLoaded', ()=>UI.init());

/* PWA: Service Worker登録（オフライン対応・ホーム画面への追加）
   新しいバージョンが有効化されたら、開いたままのタブも自動で1回だけ再読み込みして最新化する。
   （GitHubへpush→デプロイ後、アプリを開き直すだけでアイコンやインストール状態はそのままに中身だけ更新される） */
if('serviceWorker' in navigator){
  window.addEventListener('load', ()=>{
    navigator.serviceWorker.register('./sw.js').then(()=>{
      let refreshed = false;
      navigator.serviceWorker.addEventListener('controllerchange', ()=>{
        if(refreshed) return;
        refreshed = true;
        window.location.reload();
      });
    }).catch((err)=>{
      console.warn('Service Worker の登録に失敗しました', err);
    });
  });
}

/* テスト用フック（jsdomヘッドレステストから利用。通常のプレイには使用しない） */
if(typeof window!=='undefined'){
  window.__masqueTestHooks = { Game, CPU, UI, CARD_DEFS, DIFFICULTY_DEFS, SFX, MODE_DEFS, Online, Tutorial, QUICK_CHAT_PHRASES, EFFECT_STAGE_DEFS };
}
